/**
 * La géométrie de la planche 2, en unités de dessin (2 000 × 1 125) — les places
 * que les composants posent et que la chorégraphie vise. Hors des composants :
 * un module de composants n'exporte que des composants (rechargement à chaud).
 */
import { DEMAIN } from "../../contenu";
import { HORIZON, MOSAIQUE_GRILLE as G } from "./affaire.styles";

/** La place d'une tuile de la mosaïque. */
export const placeDeLaTuile = (i: number) => ({
  x: G.x + (i % G.colonnes) * (G.largeur + G.ecart),
  y: G.y + Math.floor(i / G.colonnes) * (G.hauteur + G.ecart),
});

/** La place des jalons sur l'horizon de « Demain ». */
export const PLACES_DES_JALONS = DEMAIN.map(
  (_, i) => HORIZON.debut + 160 + (i * (HORIZON.fin - HORIZON.debut - 320)) / Math.max(1, DEMAIN.length - 1),
);

export const CHEMIN_DE_L_HORIZON = `M${HORIZON.debut} ${HORIZON.y}H${HORIZON.fin}`;
