/**
 * Planche 4 — le modèle, construit sous vos yeux (≈ 45 s, cinq clics). Croquis
 * v4 validé, amendement des usages avancés compris.
 *
 * UNE CONSTRUCTION qui se bâtit d'étage en étage, et à la fin tout le modèle
 * tient dans une image :
 *   1. le socle — une dalle de lumière se lève du sol, ses neuf services s'y
 *      posent ;
 *   2. la licence d'usage — quatre tubes de verre en sortent, leur lumière monte
 *      à hauteur de leurs crédits d'usage pendant que leurs prix roulent ; la
 *      couronne d'Illimité porte sa condition à côté d'elle (ADR-139, règle 6) ;
 *   3. une seule monnaie — quatre gestes puisent dans la licence, chacun à son
 *      prix ; le soleil du jour se lève et verse ses dix crédits d'usage dans
 *      chaque tube ;
 *   4. la réserve — un réservoir s'arrime, son conduit rejoint les tubes et
 *      prend le relais ;
 *   5. les usages avancés — quatre modules s'emboîtent, chacun avec ses usages
 *      et leur prix ; ni prix de groupe ni total (William, 2026-10-14).
 */
import { useRef } from "react";

import { stepLabel, useSceneTimeline } from "@/shared/presentation-engine/motion/use-scene-timeline";
import { Glyphe } from "@/shared/components-common/systeme-du-cabinet/Glyphe";
import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";

import {
  BONUS_DU_JOUR,
  THESE_DU_MODELE,
  GESTES,
  ILLIMITE,
  NIVEAUX,
  RESERVE,
  SOCLE,
  SOCLE_LEGENDE,
  USAGES_AVANCES,
} from "../../contenu";
import { Calque, Chapeau, TitreDePlanche } from "../../pitch.styles";
import { CielDeConnexions } from "../../scene/CielDeConnexions";
import { Comete } from "../../scene/Comete";
import { apparaitre, COURBES, lancerLaComete, reveler, rouler, tracer } from "../../scene/gestes";
import { ToileDePlanche } from "../../scene/ToileDePlanche";
import { GLYPHES_DU_SOCLE } from "./glyphes-du-socle";
import {
  Bientot,
  BonusDuJour,
  ColonneDUsages,
  Couronne,
  Credits,
  Entete,
  Etage,
  EtageNom,
  EtageTexte,
  EclatDuModule,
  Geste,
  Gestes,
  HAUTEUR_PAR_CREDIT,
  Lumiere,
  Module,
  ModuleNom,
  NomDeNiveau,
  Note,
  PetitDisque,
  Prix,
  PrixDeNiveau,
  Reservoir,
  Socle,
  SocleItem,
  SoclePrix,
  SocleTete,
  SOL,
  Soleil,
  Tube,
  TeteDeTube,
  TUBES,
  Usage,
  UsagePrix,
} from "./modele.styles";

/* ── La géométrie des gestes, en unités de dessin ─────────────────────── */

const centreDuTube = (i: number) => TUBES.x[i] + TUBES.largeur / 2;
const hauteurDeLumiere = (credits: number) => credits * HAUTEUR_PAR_CREDIT;
const hautDeLaLumiere = (i: number) => SOL - hauteurDeLumiere(NIVEAUX[i].credits);
/** Le centre du soleil, posé en (1 080, 230), de 96 de côté. */
const SOLEIL = { x: 1128, y: 278 };
/** Les lignes des gestes : leur premier pixel, leur pas. */
const GESTES_Y = { haut: 552, pas: 46, hauteur: 38 };
const centreDuGeste = (i: number) => GESTES_Y.haut + i * GESTES_Y.pas + GESTES_Y.hauteur / 2;
/** Le tube où puisent les gestes : Intensif. */
const PUISE = 2;

const cheminDuGeste = (i: number) => {
  const depart = { x: centreDuTube(PUISE), y: hautDeLaLumiere(PUISE) };
  const arrivee = { x: 790, y: centreDuGeste(i) };
  return `M${depart.x} ${depart.y}Q${(depart.x + arrivee.x) / 2} ${Math.min(depart.y, arrivee.y) - 90} ${arrivee.x} ${arrivee.y}`;
};

const cheminDeLaGoutte = (i: number) => {
  const x = centreDuTube(i);
  const y = hautDeLaLumiere(i) - 8;
  return `M${SOLEIL.x} ${SOLEIL.y}Q${(SOLEIL.x + x) / 2} ${150} ${x} ${y}`;
};

/* Deux colonnes de modules : Conformité et Productivité, Clientèle et Marque. */
const COLONNES_D_USAGES = [
  { x: 1250, familles: [0, 1] },
  { x: 1575, familles: [2, 3] },
] as const;

export default function Modele() {
  const scene = useRef<HTMLDivElement>(null);

  useSceneTimeline(
    scene,
    (tl) => {
      const r = scene.current;
      if (!r) return;
      const q = (role: string) => r.querySelector(`[data-role="${role}"]`);
      const qa = (role: string) => Array.from(r.querySelectorAll(`[data-role="${role}"]`));
      const depuisLeBas = { transformOrigin: "50% 100%" };

      // L'arrivée : le titre, et le sol qui attend la construction.
      reveler(tl, q("titre"));
      tracer(tl, q("sol"), { duree: 1.1, position: "-=0.35" });
      tl.addLabel(stepLabel(0));

      // 1 · Le socle : la dalle se lève du sol, ses neuf services s'y posent.
      tl.fromTo(
        q("socle"),
        { scaleY: 0, opacity: 0, ...depuisLeBas },
        { scaleY: 1, opacity: 1, duration: 0.6, ease: COURBES.sortie, ...depuisLeBas },
      );
      apparaitre(tl, q("socle-tete"), { position: "-=0.15" });
      apparaitre(tl, qa("socle-item"), { position: "-=0.35", ecart: 0.07, y: -26 });
      tl.addLabel(stepLabel(1));

      // 2 · La licence d'usage : quatre tubes sortent du socle, leur lumière monte.
      apparaitre(tl, q("etage-licence"));
      tl.fromTo(
        qa("tube"),
        { scaleY: 0, opacity: 0, ...depuisLeBas },
        { scaleY: 1, opacity: 1, duration: 0.7, ease: COURBES.sortie, stagger: 0.1, ...depuisLeBas },
        "-=0.3",
      );
      apparaitre(tl, qa("tete-de-tube"), { position: "-=0.45", ecart: 0.1 });
      tl.addLabel("lumieres");
      tl.fromTo(
        qa("lumiere"),
        { scaleY: 0, ...depuisLeBas },
        { scaleY: 1, duration: 1.4, ease: "power2.out", stagger: 0.1, ...depuisLeBas },
        "lumieres",
      );
      NIVEAUX.forEach((niveau, i) => {
        rouler(tl, q(`credits-${i}`) as HTMLElement | null, niveau.credits, { position: `lumieres+=${i * 0.1}`, duree: 1.4 });
        rouler(tl, q(`prix-${i}`) as HTMLElement | null, niveau.prix, { position: `lumieres+=${i * 0.1}`, suffixe: " €" });
      });
      tl.fromTo(q("couronne"), { opacity: 0, scale: 0.3 }, { opacity: 1, scale: 1, duration: 0.6, ease: "back.out(2.2)" }, "-=0.25");
      tracer(tl, q("fil-illimite"), { duree: 0.45 });
      apparaitre(tl, q("note-illimite"), { position: "-=0.15" });
      tl.addLabel(stepLabel(2));

      // 3 · Une seule monnaie : les gestes puisent dans la licence ; le soleil du jour.
      apparaitre(tl, q("etage-monnaie"));
      apparaitre(tl, qa("geste"), { position: "-=0.3", ecart: 0.12 });
      GESTES.forEach((_, i) => lancerLaComete(tl, r, `geste-${i}`, { duree: 0.9, position: i === 0 ? "-=0.35" : "<0.16" }));
      tl.fromTo(q("soleil"), { y: 640, opacity: 0 }, { y: 0, opacity: 1, duration: 1.3, ease: "power3.out" }, "+=0.05");
      apparaitre(tl, q("legende-soleil"), { position: "-=0.55" });
      NIVEAUX.forEach((_, i) => lancerLaComete(tl, r, `goutte-${i}`, { duree: 0.85, position: i === 0 ? "-=0.15" : "<0.1" }));
      tl.fromTo(qa("bonus"), { opacity: 0, scaleX: 0.2 }, { opacity: 1, scaleX: 1, duration: 0.35, stagger: 0.1 }, "-=0.45");
      tl.addLabel(stepLabel(3));

      // 4 · La réserve : le réservoir s'arrime, son conduit prend le relais.
      tl.fromTo(
        q("reservoir"),
        { scaleY: 0, opacity: 0, ...depuisLeBas },
        { scaleY: 1, opacity: 1, duration: 0.7, ease: COURBES.sortie, ...depuisLeBas },
      );
      tl.fromTo(q("reserve-lumiere"), { scaleY: 0, ...depuisLeBas }, { scaleY: 1, duration: 1, ease: "power2.out", ...depuisLeBas }, "-=0.2");
      apparaitre(tl, q("etage-reserve"), { position: "-=0.7" });
      tracer(tl, q("conduit"), { duree: 0.8, position: "-=0.45" });
      lancerLaComete(tl, r, "relais", { duree: 1.1, longueur: 0.35 });
      tl.addLabel(stepLabel(4));

      // 5 · Les usages avancés : les modules s'emboîtent, et la phrase du modèle.
      apparaitre(tl, q("etage-usages"));
      tl.fromTo(
        qa("module"),
        { x: 110, opacity: 0, filter: "blur(10px)" },
        { x: 0, opacity: 1, filter: "blur(0px)", duration: 0.75, ease: COURBES.sortie, stagger: 0.14 },
        "-=0.25",
      );
      tl.fromTo(qa("module-eclat"), { opacity: 0 }, { opacity: 1, duration: 0.18, yoyo: true, repeat: 1, stagger: 0.14 }, "-=0.55");
      reveler(tl, q("these"), { position: "+=0.15" });
      tl.addLabel(stepLabel(5));
    },
    { naturelle: true },
  );

  return (
    <ToileDePlanche etiquette="Le modèle : le socle, la licence d'usage, le crédit d'usage, la réserve et les usages avancés.">
      <CielDeConnexions x={1700} y={1150} diametre={1500} intensite={0.22} />
      <div ref={scene} style={{ position: "absolute", inset: 0 }}>
        <Entete>
          <TitreDePlanche data-role="titre">Le modèle</TitreDePlanche>
          <Chapeau data-role="these">{THESE_DU_MODELE}</Chapeau>
        </Entete>

        {/* Le soleil se lève de derrière le socle : posé avant lui. */}
        <Soleil data-role="soleil">{BONUS_DU_JOUR.valeur}</Soleil>

        <Socle data-role="socle">
          <SocleTete data-role="socle-tete">
            <EtageNom>{SOCLE_LEGENDE.titre}</EtageNom>
            <SoclePrix>{SOCLE_LEGENDE.prix}</SoclePrix>
            <EtageTexte>gratuit, sans abonnement</EtageTexte>
          </SocleTete>
          {SOCLE.map((service) => (
            <SocleItem key={service} data-role="socle-item">
              <PetitDisque>
                <Glyphe trace={GLYPHES_DU_SOCLE[service]} />
              </PetitDisque>
              {service}
            </SocleItem>
          ))}
        </Socle>

        <Etage data-role="etage-licence" $x={150} $y={214} $largeur={600}>
          <EtageNom>La licence d'usage</EtageNom>
          <EtageTexte>prix HT par mois · crédits d'usage inclus chaque mois</EtageTexte>
        </Etage>
        {NIVEAUX.map((niveau, i) => {
          const hauteur = hauteurDeLumiere(niveau.credits);
          return (
            <div key={niveau.nom}>
              <TeteDeTube data-role="tete-de-tube" $x={TUBES.x[i]}>
                <NomDeNiveau>{niveau.nom}</NomDeNiveau>
                <PrixDeNiveau data-role={`prix-${i}`}>{`${niveau.prix} €`}</PrixDeNiveau>
              </TeteDeTube>
              <Tube data-role="tube" $x={TUBES.x[i]}>
                <Lumiere data-role="lumiere" $hauteur={hauteur} />
                <BonusDuJour data-role="bonus" $bas={hauteur} />
                <Credits data-role={`credits-${i}`} $bas={hauteur + 16}>
                  {new Intl.NumberFormat("fr-FR").format(niveau.credits)}
                </Credits>
                {i === NIVEAUX.length - 1 && (
                  <Couronne data-role="couronne" aria-label="illimité">
                    ∞
                  </Couronne>
                )}
              </Tube>
            </div>
          );
        })}

        <Etage data-role="legende-soleil" $x={790} $y={238} $largeur={270}>
          <EtageTexte>
            <strong style={{ color: nuit.encre }}>{BONUS_DU_JOUR.valeur} crédits d'usage</strong> {BONUS_DU_JOUR.texte}
          </EtageTexte>
        </Etage>

        <Note data-role="note-illimite" $x={790} $y={350} $largeur={400}>
          <span>
            <strong>∞ Illimité</strong> — {ILLIMITE.sansDecompte}
          </span>
          <span>{ILLIMITE.toujours}</span>
        </Note>

        <Etage data-role="etage-monnaie" $x={790} $y={470} $largeur={400}>
          <EtageNom>Une seule monnaie</EtageNom>
          <EtageTexte>le crédit d'usage — chaque geste a son prix, affiché avant</EtageTexte>
        </Etage>
        <Gestes>
          {GESTES.map((geste) => (
            <Geste key={geste.libelle} data-role="geste">
              <Prix>{geste.credits}</Prix>
              {geste.libelle}
            </Geste>
          ))}
        </Gestes>

        <Reservoir data-role="reservoir">
          <Lumiere data-role="reserve-lumiere" $hauteur={118} />
        </Reservoir>
        <Etage data-role="etage-reserve" $x={920} $y={752} $largeur={270}>
          <EtageNom>{RESERVE.titre}</EtageNom>
          <EtageTexte>
            {RESERVE.packs.map((p) => new Intl.NumberFormat("fr-FR").format(p.credits)).join(" · ")} crédits d'usage
          </EtageTexte>
          <EtageTexte>{RESERVE.packs.map((p) => `${p.prix} €`).join(" · ")} HT</EtageTexte>
          <EtageTexte>{RESERVE.regle}</EtageTexte>
        </Etage>

        <Etage data-role="etage-usages" $x={1250} $y={214} $largeur={630}>
          <EtageNom>Les usages avancés</EtageNom>
          <EtageTexte>à la carte, un à un — prix HT par mois</EtageTexte>
        </Etage>
        {COLONNES_D_USAGES.map((colonne) => (
          <ColonneDUsages key={colonne.x} $x={colonne.x}>
            {colonne.familles.map((f) => {
              const famille = USAGES_AVANCES[f];
              return (
                <Module key={famille.famille} data-role="module">
                  <EclatDuModule data-role="module-eclat" />
                  <ModuleNom>{famille.famille}</ModuleNom>
                  {famille.usages.map((u) => {
                    const bientot = "bientot" in u && u.bientot === true;
                    return (
                      <Usage key={u.nom} $bientot={bientot}>
                        <span>
                          {u.nom}
                          {bientot && <Bientot>bientôt</Bientot>}
                        </span>
                        <UsagePrix>{`${u.prix} €`}</UsagePrix>
                      </Usage>
                    );
                  })}
                </Module>
              );
            })}
          </ColonneDUsages>
        ))}

        <Calque>
          <path data-role="sol" d={`M120 ${SOL}H1880`} fill="none" stroke={nuit.accent} strokeOpacity={0.55} strokeWidth={2} />
          <path data-role="fil-illimite" d="M694 404C730 404 752 400 790 400" fill="none" stroke={nuit.accent} strokeWidth={1.4} strokeDasharray="3 4" />
          <path data-role="conduit" d={`M770 ${SOL - 14}H150`} fill="none" stroke={nuit.accent} strokeOpacity={0.7} strokeWidth={4} strokeLinecap="round" />
          {GESTES.map((_, i) => (
            <Comete key={`geste-${i}`} nom={`geste-${i}`} d={cheminDuGeste(i)} piste={false} />
          ))}
          {NIVEAUX.map((_, i) => (
            <Comete key={`goutte-${i}`} nom={`goutte-${i}`} d={cheminDeLaGoutte(i)} piste={false} />
          ))}
          <Comete nom="relais" d={`M770 ${SOL - 14}H${centreDuTube(PUISE)}V${hautDeLaLumiere(PUISE) + 40}`} piste={false} epaisseur={3.4} />
        </Calque>
      </div>
    </ToileDePlanche>
  );
}
