/**
 * Planche 3 — la différence (≈ 50 s, quatre clics). Croquis v5, go de William
 * le 2026-10-15 à 0 h 29.
 *
 * Quatre partis pris, chacun prouvé dans le code et confronté au marché : la
 * déontologie au moment du geste, le délai calculé, le secret par construction,
 * le justiciable orienté. À gauche, le cœur — la sphère de connexions du héros,
 * et quatre satellites en orbite. À chaque clic, l'orbite tourne jusqu'à amener
 * le satellite de la partie devant ; son anneau s'allume (et le reste), une
 * comète file de lui jusqu'au panneau, et le panneau joue sa preuve : les
 * tampons tombent, le dimanche glisse au lundi, le nom se brouille en jeton, le
 * récit devient un délai. Au dernier clic, les quatre anneaux sont allumés.
 */
import { useRef } from "react";

import { gsap } from "@/shared/animations/gsap";
import { num } from "@/shared/design-tokens/scale";
import { stepLabel, useSceneTimeline } from "@/shared/presentation-engine/motion/use-scene-timeline";

import { DIFFERENCE } from "../../contenu";
import { Accent, Calque, Chapeau, TitreDePlanche } from "../../pitch.styles";
import { Comete } from "../../scene/Comete";
import { apparaitre, COURBES, lancerLaComete, reveler } from "../../scene/gestes";
import { ToileDePlanche } from "../../scene/ToileDePlanche";
import { Coeur } from "./Coeur";
import { decalagePour, type EtatDuCoeur } from "./coeur.geometrie";
import { Entete } from "./difference.styles";
import { Panneaux } from "./Panneaux";

/** La comète qui part du satellite de devant (500, 813) vers le panneau. */
const ELAN = "M500 813C690 900 880 640 1000 300";

type Tl = gsap.core.Timeline;

/** La preuve de chaque partie : ce qui se voit jouer, une fois le panneau entré. */
const PREUVES: Record<(typeof DIFFERENCE.parties)[number]["id"], (tl: Tl, p: Element, racine: Element) => void> = {
  deontologie: (tl, p) => {
    tl.fromTo(
      p.querySelectorAll('[data-role="tampon"]'),
      { opacity: 0, scale: 1.3, rotation: -5, filter: "blur(6px)" },
      { opacity: 1, scale: 1, rotation: 0, filter: "blur(0px)", duration: 0.45, ease: "back.out(1.8)", stagger: 0.32 },
    );
  },
  delai: (tl, p) => {
    const un = (role: string) => p.querySelector(`[data-role="${role}"]`);
    apparaitre(tl, un("date-acte"), { duree: 0.5 });
    tl.fromTo(un("fleche"), { clipPath: "inset(0 100% 0 0)" }, { clipPath: "inset(0 0% 0 0)", duration: 0.6, ease: "power2.inOut" });
    apparaitre(tl, un("date-tombe"), { duree: 0.45, position: "-=0.1" });
    tl.fromTo(un("rature"), { scaleX: 0 }, { scaleX: 1, duration: 0.4, ease: "power2.out" }, "+=0.25");
    tl.to(un("date-tombe"), { opacity: 0.45, duration: 0.3 }, "<0.2");
    tl.fromTo(
      un("date-reportee"),
      { x: -num(230), opacity: 0 },
      { x: 0, opacity: 1, duration: 0.7, ease: COURBES.sortie },
      "-=0.1",
    );
    tl.fromTo(un("sceau"), { opacity: 0, scale: 1.5, rotation: -6 }, { opacity: 1, scale: 1, rotation: 0, duration: 0.4, ease: "back.out(2)" }, "-=0.15");
  },
  secret: (tl, p) => {
    apparaitre(tl, p.querySelectorAll('[data-role="masque-ligne"]'), { ecart: 0.12, duree: 0.5 });
    tl.to(p.querySelector('[data-role="jeton"]'), {
      duration: 1.1,
      ease: "none",
      scrambleText: { text: "[PERSON_1]", chars: "ABCDEFGHIJKLMNOPQRSTUVWXYZ_[]0123456789", speed: 0.5, revealDelay: 0.35 },
    }, "+=0.15");
  },
  justiciable: (tl, p, racine) => {
    apparaitre(tl, p.querySelectorAll('[data-role="etape"]'), { ecart: 0.12, duree: 0.5 });
    lancerLaComete(tl, racine, "parcours", { duree: 1.5, longueur: 0.18, position: "-=0.1" });
    const anneaux = p.querySelectorAll('[data-role="anneau-etape"]');
    anneaux.forEach((anneau, i) => {
      tl.fromTo(anneau, { opacity: 0 }, { opacity: 1, duration: 0.3 }, `<${i === 0 ? 0 : 0.5}`);
    });
  },
};

export default function Difference() {
  const scene = useRef<HTMLDivElement>(null);
  const etat = useRef<EtatDuCoeur>({ decalage: decalagePour(0) });
  const rendreRef = useRef<() => void>(() => undefined);

  useSceneTimeline(
    scene,
    (tl) => {
      const r = scene.current;
      if (!r) return;
      const q = (role: string) => r.querySelector(`[data-role="${role}"]`);
      const rendre = () => rendreRef.current();

      // L'arrivée : le titre, son chapeau ; le cœur entre de lui-même (son horloge).
      // Le titre entre d'un bloc : son mot d'accent peint son dégradé dans SA boîte,
      // et des mots découpés et transformés en sortiraient.
      apparaitre(tl, q("titre-planche"), { duree: 0.7 });
      apparaitre(tl, q("chapeau"), { position: "-=0.35" });
      tl.addLabel(stepLabel(0));

      DIFFERENCE.parties.forEach((partie, k) => {
        const debut = `partie-${k}`;
        tl.addLabel(debut);
        const panneau = q(`partie-${partie.id}`);
        if (!panneau) return;
        // L'orbite amène le satellite devant ; le panneau d'avant s'efface.
        if (k > 0) {
          tl.to(etat.current, { decalage: decalagePour(k), duration: 1, ease: COURBES.sortie, onUpdate: rendre }, debut);
          tl.to(q(`partie-${DIFFERENCE.parties[k - 1].id}`), { opacity: 0, y: -18, filter: "blur(8px)", duration: 0.4, ease: "power2.in" }, debut);
        }
        // Son anneau s'allume, et une comète file de lui au panneau.
        tl.fromTo(q(`anneau-${partie.id}`), { opacity: 0 }, { opacity: 1, duration: 0.5 }, `${debut}+=0.5`);
        lancerLaComete(tl, r, "elan", { duree: 0.8, longueur: 0.4, position: `${debut}+=0.55` });
        // Le panneau entre : son rang et son titre, puis sa preuve, puis ses lignes.
        tl.set(panneau, { opacity: 1, y: 0, filter: "blur(0px)" }, `${debut}+=0.7`);
        apparaitre(tl, panneau.querySelector('[data-role="rang"]'), { position: `${debut}+=0.75`, duree: 0.4 });
        reveler(tl, panneau.querySelector('[data-role="titre"]'), { position: `${debut}+=0.8` });
        PREUVES[partie.id](tl, panneau, r);
        apparaitre(tl, panneau.querySelectorAll('[data-role="ligne"]'), { ecart: 0.18, duree: 0.55, position: "-=0.2" });
        tl.addLabel(stepLabel(k + 1));
      });
    },
    { naturelle: true },
  );

  return (
    <ToileDePlanche etiquette={`${DIFFERENCE.titre}. ${DIFFERENCE.chapeau}`}>
      <div ref={scene} style={{ position: "absolute", inset: 0 }}>
        <Entete>
          <TitreDePlanche data-role="titre-planche">
            La <Accent>différence</Accent>
          </TitreDePlanche>
          <Chapeau data-role="chapeau">{DIFFERENCE.chapeau}</Chapeau>
        </Entete>
        <Coeur etat={etat} rendreRef={rendreRef} />
        <Panneaux />
        <Calque>
          <Comete nom="elan" d={ELAN} piste={false} epaisseur={3.4} />
        </Calque>
      </div>
    </ToileDePlanche>
  );
}
