/**
 * Les gestes des planches — ce qu'une timeline de scène sait faire, écrit une
 * fois : lancer une comète, tracer un chemin, révéler un titre, faire rouler un
 * nombre, allumer une impulsion. Chaque geste s'AJOUTE à la timeline de la
 * planche (`useSceneTimeline`, option `naturelle`) : il avance au clic et
 * recule avec lui, sans état à remettre d'aplomb.
 *
 * Les éléments se retrouvent par leurs attributs (`data-comete`, `data-role`),
 * dans le conteneur de la planche : une planche montée deux fois (la vue
 * présentateur) ne confond pas les siennes.
 */
import { gsap, SplitText } from "@/shared/animations/gsap";

type Position = gsap.Position | undefined;

/** Les courbes du deck : la sortie keynote du moteur, et un doux-doux pour les trajets. */
export const COURBES = { sortie: "keynote", trajet: "power2.inOut" } as const;

/**
 * Lance la comète `nom` le long de son chemin : la tête part, la traînée la
 * suit, et tout s'éteint à l'arrivée. `longueur` : la traînée, en fraction du
 * chemin.
 */
export function lancerLaComete(
  tl: gsap.core.Timeline,
  racine: Element,
  nom: string,
  { duree = 1.2, longueur = 0.3, position }: { duree?: number; longueur?: number; position?: Position } = {},
): void {
  const groupe = racine.querySelector(`[data-comete="${nom}"]`);
  const trainee = groupe?.querySelector<SVGPathElement>('[data-role="trainee"]');
  const tete = groupe?.querySelector<SVGGElement>('[data-role="tete"]');
  const degrade = groupe?.querySelector<SVGLinearGradientElement>('[data-role="degrade"]');
  if (!trainee || !tete || !degrade) return;
  const total = trainee.getTotalLength();
  const etat = { t: 0 };
  const dessiner = () => {
    const h = etat.t * (1 + longueur);
    const avant = Math.min(1, h);
    const arriere = Math.max(0, Math.min(1, h - longueur));
    trainee.style.strokeDasharray = `${Math.max(0.001, (avant - arriere) * total)} ${total * 2}`;
    trainee.style.strokeDashoffset = `${-arriere * total}`;
    trainee.style.opacity = etat.t > 0 && etat.t < 1 ? "1" : "0";
    const p = trainee.getPointAtLength(avant * total);
    const q = trainee.getPointAtLength(arriere * total);
    tete.setAttribute("transform", `translate(${p.x.toFixed(1)} ${p.y.toFixed(1)})`);
    tete.style.opacity = etat.t > 0 && h < 1 ? "1" : "0";
    degrade.setAttribute("x1", q.x.toFixed(1));
    degrade.setAttribute("y1", q.y.toFixed(1));
    degrade.setAttribute("x2", p.x.toFixed(1));
    degrade.setAttribute("y2", p.y.toFixed(1));
  };
  tl.fromTo(etat, { t: 0 }, { t: 1, duration: duree, ease: COURBES.trajet, onUpdate: dessiner }, position);
}

/** Trace un chemin SVG de son début à sa fin — un horizon, un conduit, une orbite. */
export function tracer(
  tl: gsap.core.Timeline,
  cible: gsap.TweenTarget,
  { duree = 1, position }: { duree?: number; position?: Position } = {},
): void {
  tl.fromTo(cible, { drawSVG: "0%" }, { drawSVG: "100%", duration: duree, ease: COURBES.trajet }, position);
}

/**
 * Révèle un texte mot à mot : chaque mot monte d'un cran, sort du flou et
 * s'allume. Le texte reste un seul nœud pour un lecteur d'écran (SplitText
 * pose `aria-label` sur le conteneur découpé).
 */
export function reveler(
  tl: gsap.core.Timeline,
  cible: Element | null,
  { position, par = "words", ecart = 0.05 }: { position?: Position; par?: "words" | "chars"; ecart?: number } = {},
): void {
  if (!cible) return;
  const decoupe = SplitText.create(cible, { type: par, aria: "auto" });
  const morceaux = par === "chars" ? decoupe.chars : decoupe.words;
  tl.fromTo(
    morceaux,
    { yPercent: 70, opacity: 0, filter: "blur(10px)" },
    { yPercent: 0, opacity: 1, filter: "blur(0px)", duration: 0.7, ease: COURBES.sortie, stagger: ecart },
    position,
  );
}

/** Fait apparaître un bloc : il monte d'un cran et sort du flou. */
export function apparaitre(
  tl: gsap.core.Timeline,
  cible: gsap.TweenTarget,
  { position, duree = 0.6, ecart = 0.08, y = 18 }: { position?: Position; duree?: number; ecart?: number; y?: number } = {},
): void {
  tl.fromTo(
    cible,
    { y, opacity: 0, filter: "blur(8px)" },
    { y: 0, opacity: 1, filter: "blur(0px)", duration: duree, ease: COURBES.sortie, stagger: ecart },
    position,
  );
}

/**
 * Fait rouler un nombre jusqu'à sa valeur, au format français (« 1 500 »). Le
 * texte final est écrit dans le DOM dès le départ : un lecteur d'écran, un
 * mouvement réduit ou une capture lisent la vraie valeur.
 */
export function rouler(
  tl: gsap.core.Timeline,
  cible: HTMLElement | null,
  valeur: number,
  { position, duree = 1.1, suffixe = "" }: { position?: Position; duree?: number; suffixe?: string } = {},
): void {
  if (!cible) return;
  const format = new Intl.NumberFormat("fr-FR");
  const etat = { v: 0 };
  tl.fromTo(
    etat,
    { v: 0 },
    {
      v: valeur,
      duration: duree,
      ease: "power3.out",
      onUpdate: () => {
        cible.textContent = `${format.format(Math.round(etat.v))}${suffixe}`;
      },
    },
    position,
  );
}

/** Une impulsion : un anneau qui s'élargit et s'éteint, là où quelque chose arrive. */
export function impulsion(tl: gsap.core.Timeline, anneau: gsap.TweenTarget, position?: Position): void {
  tl.fromTo(
    anneau,
    { scale: 0.6, opacity: 0.9 },
    { scale: 2.1, opacity: 0, duration: 0.9, ease: "power2.out" },
    position,
  );
}
