/**
 * Le ciel d'une planche — la sphère de connexions du héros, au loin : immense,
 * pâle, qui tourne lentement derrière la composition. D'une planche à l'autre,
 * elle dit que c'est le même système qu'on regarde, de plus près ou de plus
 * loin ; le halo qui l'accompagne respire comme celui du centre de la landing.
 *
 * Elle se pose DANS la toile, en unités de dessin (2 000 × 1 125, `pitch.styles`),
 * et peut en déborder : la nuit de la planche la coupe au bord de l'écran.
 */
import { useLayoutEffect, useRef } from "react";
import { useReducedMotion } from "framer-motion";
import { styled } from "styled-components";

import { breathe } from "@/shared/animations/motion.keyframes";
import { useHorlogeDeScene } from "@/shared/animations/scene/horloge";
import { SphereDeConnexions, type PoigneeDeLaSphere } from "@/shared/animations/scene/SphereDeConnexions";
import { withOpacity } from "@/shared/design-tokens/color";
import { num } from "@/shared/design-tokens/scale";
import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";

/** Un tour de la sphère lointaine : deux fois plus lent que celle du héros. */
const TOUR_MS = 92_000;

const Ciel = styled.div`
  position: absolute;
  pointer-events: none;
`;

const Halo = styled.div`
  position: absolute;
  inset: -22%;
  border-radius: 50%;
  background: radial-gradient(
    closest-side,
    ${withOpacity(nuit.accent, 0.12)},
    ${withOpacity(nuit.marque, 0.06)} 55%,
    transparent
  );
  animation: ${breathe(0.75, 1.04)} 8s ease-in-out infinite;

  @media (prefers-reduced-motion: reduce) {
    animation: none;
  }
`;

const Globe = styled.div`
  position: absolute;
  inset: 0;
`;

export function CielDeConnexions({
  x,
  y,
  diametre,
  intensite = 0.35,
}: {
  /** Le centre de la sphère, en unités de dessin de la toile. */
  x: number;
  y: number;
  diametre: number;
  /** L'opacité de la sphère : pâle, elle reste un fond. */
  intensite?: number;
}) {
  const reduit = useReducedMotion() === true;
  const cadre = useRef<HTMLDivElement>(null);
  const sphere = useRef<PoigneeDeLaSphere>(null);
  const etat = useRef({ lacet: 0.9, apparition: 0 });

  useHorlogeDeScene(
    (dt) => {
      const e = etat.current;
      e.lacet += (dt / TOUR_MS) * Math.PI * 2;
      e.apparition = Math.min(1, e.apparition + dt / 1800);
      sphere.current?.dessiner(e.lacet, e.apparition, 0);
    },
    { actif: !reduit, cible: cadre },
  );

  useLayoutEffect(() => {
    if (reduit) sphere.current?.dessiner(etat.current.lacet, 1, 0);
  }, [reduit]);

  return (
    <Ciel
      ref={cadre}
      aria-hidden="true"
      style={{
        left: num(x - diametre / 2),
        top: num(y - diametre / 2),
        width: num(diametre),
        height: num(diametre),
      }}
    >
      <Halo />
      <Globe style={{ opacity: intensite }}>
        <SphereDeConnexions
          diametre={num(diametre)}
          couleur={nuit.accent}
          nombreDePoints={120}
          voisins={3}
          densite={1.25}
          ref={sphere}
        />
      </Globe>
    </Ciel>
  );
}
