/**
 * La mosaïque — les douze disques du système du cabinet, aplatis en tuiles.
 * Les tuiles sont posées à leur place finale et invisibles ; au quatrième clic,
 * la chorégraphie (`choregraphie.ts`) les fait partir de la place EXACTE de leur
 * planète (un FLIP : la planète devient tuile), puis une vague de lumière passe
 * sur toutes : onze services, une seule plateforme, rien à assembler.
 */
import { Glyphe } from "@/shared/components-common/systeme-du-cabinet/Glyphe";
import { NOEUDS_DU_RESEAU } from "@/shared/components-common/systeme-du-cabinet/systeme.reseau";

import { MOSAIQUE } from "../../contenu";
import { placeDeLaTuile } from "./affaire.geometrie";
import { Annonce, AnnonceTexte, AnnonceTitre, Tuile, TuileDisque, TuileNom } from "./affaire.styles";

export function Mosaique() {
  return (
    <>
      {NOEUDS_DU_RESEAU.map((noeud, i) => {
        const { x, y } = placeDeLaTuile(i);
        return (
          <Tuile key={noeud.id} data-role="tuile" data-tuile={noeud.id} $x={x} $y={y} $tiroir={noeud.tiroir === true}>
            <TuileDisque data-role="tuile-contenu">
              <Glyphe trace={noeud.glyphe} />
            </TuileDisque>
            <TuileNom data-role="tuile-contenu">{noeud.libelle}</TuileNom>
          </Tuile>
        );
      })}
      <Annonce data-role="annonce">
        <AnnonceTitre>{MOSAIQUE.annonce}</AnnonceTitre>
        <AnnonceTexte>{MOSAIQUE.detail}</AnnonceTexte>
      </Annonce>
    </>
  );
}
