/**
 * La toile d'une planche — la nuit plein cadre, et une composition de
 * 1 600 × 900 px (16:9) mise à l'échelle de l'écran d'un bloc.
 *
 * C'est le cadre de Keynote ou de reveal.js : chaque planche se compose une
 * fois, à des positions exactes (une comète part d'un point et arrive à un
 * autre), et tout grandit ensemble sur l'écran de la salle. La nuit, elle,
 * remplit tout l'écran : un projecteur 16:10 ou 4:3 ne montre aucune bande.
 *
 * L'échelle s'écrit dans le style directement, sans état React : un ancêtre
 * mis à l'échelle doit l'être AVANT que ses enfants se mesurent (le système du
 * cabinet mesure sa scène à l'écran — `SystemeDuCabinet`, cadre « planche »).
 */
import { useLayoutEffect, useRef, type ReactNode } from "react";
import { styled } from "styled-components";

import { withOpacity } from "@/shared/design-tokens/color";
import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";
import { px } from "@/shared/design-tokens/scale";

import { TOILE } from "../pitch.styles";

const Nuit = styled.section`
  position: relative;
  width: 100%;
  height: 100dvh;
  overflow: hidden;
  isolation: isolate;
  color: ${nuit.encre};
  background:
    radial-gradient(120% 90% at 50% 42%, ${withOpacity(nuit.marque, 0.1)}, transparent 62%),
    ${nuit.fondDegrade};
  user-select: none;
`;

/** Ce qui vit derrière la composition, à la taille de l'écran : le ciel. */
const Fond = styled.div`
  position: absolute;
  inset: 0;
  pointer-events: none;
`;

const Toile = styled.div`
  position: absolute;
  left: 50%;
  top: 50%;
  width: ${px(2000)};
  height: ${px(1125)};
  transform-origin: center center;
  transform: translate(-50%, -50%);
`;

export function ToileDePlanche({
  etiquette,
  fond,
  children,
}: {
  /** Ce que la planche dit, en une phrase, à un lecteur d'écran. */
  etiquette: string;
  /** Le ciel : ce qui vit derrière, plein écran. */
  fond?: ReactNode;
  children: ReactNode;
}) {
  const cadre = useRef<HTMLElement>(null);
  const toile = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const el = cadre.current;
    const t = toile.current;
    if (!el || !t) return;
    const poser = () => {
      const echelle = Math.min(el.clientWidth / TOILE.largeur, el.clientHeight / TOILE.hauteur);
      if (!(echelle > 0)) return;
      t.style.transform = `translate(-50%, -50%) scale(${echelle})`;
    };
    poser();
    const observateur = new ResizeObserver(poser);
    observateur.observe(el);
    return () => observateur.disconnect();
  }, []);

  return (
    <Nuit ref={cadre} aria-label={etiquette}>
      {fond && <Fond aria-hidden="true">{fond}</Fond>}
      <Toile ref={toile}>{children}</Toile>
    </Nuit>
  );
}
