/**
 * Une comète — le trait de lumière du système du cabinet, détaché de lui : une
 * tête qui brille et une traînée qui la suit, le long d'un chemin SVG. Sur la
 * landing, le trait va d'un service à l'autre ; sur les planches, il porte un
 * dossier, une demande, un crédit d'usage — le même geste, partout : quelque
 * chose passe d'un endroit à l'autre.
 *
 * Le composant pose les tracés ; la timeline de la planche la LANCE
 * (`lancerLaComete`, `gestes.ts`) : elle avance avec le clic, recule avec lui.
 * Les identifiants viennent de `useId` : la vue présentateur peut monter deux
 * fois la même planche, et un dégradé nommé deux fois se perdrait.
 */
import { useId } from "react";

import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";

export function Comete({
  nom,
  d,
  piste = true,
  epaisseur = 2.6,
}: {
  /** Le nom par lequel la timeline la retrouve (`data-comete`). */
  nom: string;
  /** Le chemin SVG, dans le repère de la toile (1 600 × 900). */
  d: string;
  /** La piste en pointillés que la comète emprunte, visible au repos. */
  piste?: boolean;
  epaisseur?: number;
}) {
  const id = useId().replace(/:/g, "");
  const degrade = `comete-${id}`;
  const halo = `comete-halo-${id}`;
  return (
    <g data-comete={nom}>
      <defs>
        <linearGradient id={degrade} data-role="degrade" gradientUnits="userSpaceOnUse">
          <stop offset="0" stopColor={nuit.marque} stopOpacity="0" />
          <stop offset="0.7" stopColor={nuit.accent} stopOpacity="0.75" />
          <stop offset="1" stopColor={nuit.eclat} stopOpacity="1" />
        </linearGradient>
        <filter id={halo} x="-300%" y="-300%" width="700%" height="700%">
          <feGaussianBlur stdDeviation="4" />
        </filter>
      </defs>
      {piste && (
        <path
          data-role="piste"
          d={d}
          fill="none"
          stroke={nuit.accent}
          strokeOpacity={0.3}
          strokeWidth={1.2}
          strokeDasharray="2 7"
          strokeLinecap="round"
        />
      )}
      <path
        data-role="trainee"
        d={d}
        fill="none"
        stroke={`url(#${degrade})`}
        strokeWidth={epaisseur}
        strokeLinecap="round"
        style={{ opacity: 0 }}
      />
      <g data-role="tete" style={{ opacity: 0 }}>
        <circle r={9} fill={nuit.accent} filter={`url(#${halo})`} />
        <circle r={3.2} fill={nuit.eclat} />
      </g>
    </g>
  );
}
