/**
 * Planche 1 — le nom (≈ 20 s, un clic). Croquis v4 validé.
 *
 * LE HÉROS DE LA LANDING, monté tel quel : le système du cabinet, en cadre
 * « planche ». Au repos, une dizaine d'outils épars, éteints, autour de
 * « JURIS-POWER ». Au clic, chaque outil est tiré en orbite et relié, la sphère
 * s'allume, et le nom se recompose en « JURIS-CONNECT » — le nom dit ce que le
 * système fait. À gauche, la phrase grise se dissout et le titre s'écrit, avec la
 * grammaire du titre d'affiche de la landing.
 */
import { useContext, useRef } from "react";
import { styled } from "styled-components";

import { TexteQuiSeRecompose } from "@/shared/animations/TexteQuiSeRecompose";
import { SystemeDuCabinet } from "@/shared/components-common/systeme-du-cabinet/SystemeDuCabinet";
import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";
import { px } from "@/shared/design-tokens/scale";
import { FragmentStepContext } from "@/shared/presentation-engine/fragments";
import { stepLabel, useSceneTimeline } from "@/shared/presentation-engine/motion/use-scene-timeline";

import { ACCUEIL, EVENEMENT } from "../contenu";
import { Accent, Chapeau, FiletDeSignature, Surtitre } from "../pitch.styles";
import { ToileDePlanche } from "../scene/ToileDePlanche";
import { apparaitre, COURBES, reveler } from "../scene/gestes";

/* Le système DÉBORDE à droite, comme sur la landing : ses libellés de côté y
   gagnent de l'air ; à gauche, jamais — le titre est là. */
const CadreDuSysteme = styled.div`
  position: absolute;
  left: ${px(860)};
  top: ${px(30)};
  width: ${px(1200)};
  height: ${px(1065)};
`;

const Colonne = styled.div`
  position: absolute;
  left: ${px(120)};
  top: 0;
  bottom: 0;
  width: ${px(730)};
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: ${px(34)};
`;

const Entete = styled.div`
  position: absolute;
  left: ${px(120)};
  top: ${px(80)};
`;

/** Les deux titres occupent la même place : l'un se dissout, l'autre s'écrit. */
const Superposition = styled.div`
  display: grid;

  & > * {
    grid-area: 1 / 1;
  }
`;

const Titre = styled.h1`
  margin: 0;
  font-size: ${px(70)};
  font-weight: 900;
  line-height: 1.04;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  white-space: pre-line;
  color: ${nuit.encre};
`;

const TitreEteint = styled(Titre)`
  color: ${nuit.encreDouce};
  opacity: 0.75;
`;

const Promesse = styled(Chapeau)`
  max-width: ${px(640)};
`;

export default function Accueil() {
  const step = useContext(FragmentStepContext);
  const relie = step >= 1;
  const scene = useRef<HTMLDivElement>(null);

  useSceneTimeline(
    scene,
    (tl) => {
      const racine = scene.current;
      if (!racine) return;
      const q = (role: string) => racine.querySelector(`[data-role="${role}"]`);
      // L'arrivée : l'événement, puis la phrase grise.
      apparaitre(tl, q("entete"), { duree: 0.7 });
      reveler(tl, q("avant"), { position: "-=0.3", ecart: 0.06 });
      tl.addLabel(stepLabel(0));
      // Le clic : la phrase grise se dissout, le titre s'écrit, la promesse suit.
      tl.to(q("avant"), { yPercent: -18, opacity: 0, filter: "blur(12px)", duration: 0.55, ease: COURBES.sortie });
      reveler(tl, q("ligne"), { position: "-=0.15", par: "chars", ecart: 0.022 });
      // Le mot d'accent ne se découpe pas : son dégradé est peint dans SA boîte,
      // et des lettres transformées en sortiraient. Il s'éclaire d'un balayage.
      tl.fromTo(
        q("accent"),
        { clipPath: "inset(-20% 100% -20% 0)" },
        { clipPath: "inset(-20% 0% -20% 0)", duration: 0.85, ease: COURBES.sortie },
        "-=0.2",
      );
      tl.fromTo(q("filet"), { scaleX: 0, opacity: 0 }, { scaleX: 1, opacity: 1, duration: 0.9, ease: COURBES.sortie }, "-=0.45");
      apparaitre(tl, q("promesse"), { position: "-=0.55", duree: 0.8 });
      tl.addLabel(stepLabel(1));
    },
    { naturelle: true },
  );

  return (
    <ToileDePlanche etiquette={`${ACCUEIL.titre.join(" ")} ${ACCUEIL.promesse}`}>
      <div ref={scene} style={{ position: "absolute", inset: 0 }}>
        <CadreDuSysteme>
          <SystemeDuCabinet
            cadre="planche"
            dispersion={{ reliee: relie }}
            terme={<TexteQuiSeRecompose de={EVENEMENT.ancienNom} vers="Juris-Connect" actif={relie} duree={1.3} />}
          />
        </CadreDuSysteme>

        <Entete data-role="entete">
          <Surtitre>{EVENEMENT.surtitre}</Surtitre>
        </Entete>

        <Colonne>
          <Superposition>
            <TitreEteint as="p" data-role="avant">
              {ACCUEIL.avant.join("\n")}
            </TitreEteint>
            <Titre>
              <span data-role="ligne">{ACCUEIL.titre[0]}</span>
              {"\n"}
              <Accent data-role="accent" style={{ display: "inline-block" }}>
                {ACCUEIL.titre[1]}
              </Accent>
            </Titre>
          </Superposition>
          <FiletDeSignature data-role="filet" />
          <Promesse data-role="promesse">{ACCUEIL.promesse}</Promesse>
        </Colonne>
      </div>
    </ToileDePlanche>
  );
}
