/**
 * La chorégraphie de la planche 2 — ce que chaque clic fait jouer.
 *
 * Elle ne vit PAS dans une timeline construite d'avance, à l'inverse des autres
 * planches : les gestes de celle-ci partent de la place, à l'instant du clic, de
 * planètes qui tournent. La mosaïque part de la position EXACTE de chaque disque
 * (un FLIP), et la comète d'un tampon part de la planète où le trait vient
 * d'arriver. Chaque transition se construit donc au clic, et `poserLEtat` remet
 * la planche d'aplomb à n'importe quel pas — une arrivée par l'arrière, un pas
 * en arrière, le mouvement réduit.
 */
import { gsap } from "@/shared/animations/gsap";
import { RYTHME_DU_FLUX } from "@/shared/components-common/systeme-du-cabinet/systeme.flux";
import { num, px } from "@/shared/design-tokens/scale";

import { TEMPS_DE_L_AFFAIRE } from "../../contenu";
import { apparaitre, COURBES, lancerLaComete, tracer } from "../../scene/gestes";
import { PLACES_DES_JALONS } from "./affaire.geometrie";
import { HORIZON } from "./affaire.styles";

/** La cadence du système sur cette planche : deux fois la vitesse de la landing. */
export const CADENCE = 2;
export const PERIODE_MS = RYTHME_DU_FLUX.periodeMs / CADENCE;
export const TRAIT_MS = RYTHME_DU_FLUX.traitMs / CADENCE;

/** Le nombre de tampons posés au bout du temps `temps` (0 à 3). */
export const posesALaFinDu = (temps: number): number =>
  TEMPS_DE_L_AFFAIRE.slice(0, Math.max(0, Math.min(3, temps))).reduce((n, t) => n + t.tampons.length, 0);

/** Ce que dit la légende, pas par pas. */
export const LEGENDES = [
  "Une affaire, du rendez-vous à l'encaissement",
  ...TEMPS_DE_L_AFFAIRE.map((t, i) => `${i + 1} · ${t.titre}`),
  "Onze services, et bien plus",
  "La feuille de route",
] as const;

const tous = (racine: Element, role: string) => Array.from(racine.querySelectorAll<HTMLElement>(`[data-role="${role}"]`));
const un = (racine: Element, role: string) => racine.querySelector<HTMLElement>(`[data-role="${role}"]`);

/** Un point de l'écran, dans le repère de dessin de la toile (2 000 × 1 125). */
function versLeDessin(racine: Element, x: number, y: number) {
  const r = racine.getBoundingClientRect();
  return { x: ((x - r.left) * 2000) / r.width, y: ((y - r.top) * 1125) / r.height };
}

/** Le facteur entre un pixel de l'écran et un pixel de la toile (elle est mise à l'échelle). */
const echelleDeLaToile = (racine: Element) => racine.getBoundingClientRect().width / num(2000);

/**
 * La comète d'un tampon : de la planète `service`, où le trait vient d'arriver,
 * jusqu'au bas du dossier, où le tampon va se poser.
 */
export function volerVersLeDossier(racine: HTMLElement, service: string): void {
  const disque = racine.querySelector(`[data-service="${service}"] > span`);
  const corps = un(racine, "corps");
  const trainee = racine.querySelector<SVGPathElement>('[data-comete="vol"] [data-role="trainee"]');
  if (!disque || !corps || !trainee) return;
  const d = disque.getBoundingClientRect();
  const c = corps.getBoundingClientRect();
  const a = versLeDessin(racine, d.left + d.width / 2, d.top + d.height / 2);
  const b = versLeDessin(racine, c.left + c.width * 0.08, c.bottom - c.height * 0.04);
  trainee.setAttribute("d", `M${a.x.toFixed(1)} ${a.y.toFixed(1)}Q${((a.x + b.x) / 2).toFixed(1)} ${(Math.min(a.y, b.y) - 140).toFixed(1)} ${b.x.toFixed(1)} ${b.y.toFixed(1)}`);
  const tl = gsap.timeline();
  lancerLaComete(tl, racine, "vol", { duree: 0.55, longueur: 0.45 });
}

/** La légende change en se brouillant, à la manière du nom de la planche 1. */
export function changerLaLegende(racine: Element, pas: number, instant: boolean): void {
  const legende = un(racine, "legende");
  if (!legende) return;
  const texte = LEGENDES[Math.max(0, Math.min(LEGENDES.length - 1, pas))];
  if (instant) {
    gsap.killTweensOf(legende);
    legende.textContent = texte;
    return;
  }
  gsap.to(legende, { duration: 0.8, ease: "none", scrambleText: { text: texte, chars: "upperCase", speed: 0.6 } });
}

/** L'entrée sur la planche : le titre, la légende, le dossier qui glisse depuis la droite. */
export function entrer(racine: HTMLElement): gsap.core.Timeline {
  const tl = gsap.timeline();
  apparaitre(tl, un(racine, "titre-affaire"), { duree: 0.7 });
  apparaitre(tl, un(racine, "legende"), { position: "-=0.35" });
  tl.fromTo(
    un(racine, "chemise"),
    { x: 80, opacity: 0, filter: "blur(10px)" },
    { x: 0, opacity: 1, filter: "blur(0px)", duration: 0.8, ease: COURBES.sortie },
    "-=0.4",
  );
  return tl;
}

/** Le quatrième clic : chaque planète devient sa tuile, depuis sa place exacte (FLIP). */
export function versLaMosaique(racine: HTMLElement): gsap.core.Timeline {
  const tl = gsap.timeline();
  const echelle = echelleDeLaToile(racine);
  tous(racine, "tuile").forEach((tuile, i) => {
    const disque = racine.querySelector(`[data-service="${tuile.dataset.tuile}"] > span`);
    const t = tuile.getBoundingClientRect();
    const d = disque?.getBoundingClientRect();
    const depart =
      d && d.width > 0
        ? {
            x: (d.left + d.width / 2 - (t.left + t.width / 2)) / echelle,
            y: (d.top + d.height / 2 - (t.top + t.height / 2)) / echelle,
            scaleX: d.width / t.width,
            scaleY: d.height / t.height,
          }
        : { x: 0, y: 40, scaleX: 0.3, scaleY: 0.3 };
    tl.fromTo(
      tuile,
      { ...depart, borderRadius: "50%", opacity: 1 },
      { x: 0, y: 0, scaleX: 1, scaleY: 1, borderRadius: px(12), duration: 0.95, ease: COURBES.sortie },
      i * 0.035,
    );
  });
  tl.to(un(racine, "systeme"), { opacity: 0, duration: 0.3 }, 0.02);
  tl.fromTo(tous(racine, "tuile-contenu"), { opacity: 0 }, { opacity: 1, duration: 0.45, stagger: 0.02 }, 0.6);
  // La vague : la lumière passe sur chaque tuile, de la première à la dernière.
  tous(racine, "tuile").forEach((tuile, i) => {
    tl.add(() => tuile.setAttribute("data-allumee", "true"), 1.15 + i * 0.07);
    tl.add(() => tuile.setAttribute("data-allumee", "false"), 1.6 + i * 0.07);
  });
  tl.fromTo(un(racine, "annonce"), { opacity: 0, y: 24 }, { opacity: 1, y: 0, duration: 0.6, ease: COURBES.sortie }, 1.5);
  return tl;
}

/** Le cinquième clic : la mosaïque aspirée dans le premier jalon, puis l'horizon de demain. */
export function versDemain(racine: HTMLElement): gsap.core.Timeline {
  const tl = gsap.timeline();
  const cible = { x: PLACES_DES_JALONS[0], y: HORIZON.y };
  tous(racine, "tuile").forEach((tuile, i) => {
    const t = tuile.getBoundingClientRect();
    const c = versLeDessin(racine, t.left + t.width / 2, t.top + t.height / 2);
    const vers = { x: ((cible.x - c.x) * num(2000)) / 2000, y: ((cible.y - c.y) * num(1125)) / 1125 };
    tl.to(tuile, { x: `+=${vers.x}`, y: `+=${vers.y}`, scale: 0.04, opacity: 0, duration: 0.7, ease: "power3.in" }, i * 0.03);
  });
  tl.to([un(racine, "chemise"), un(racine, "annonce")], { opacity: 0, x: 40, duration: 0.45, ease: "power2.in" }, 0);
  tl.to(un(racine, "titre-affaire"), { opacity: 0, y: -24, duration: 0.4, ease: "power2.in" }, 0.1);
  apparaitre(tl, un(racine, "titre-demain"), { position: 0.5, duree: 0.7 });
  const depart = 0.75;
  const duree = 1.6;
  tl.set(un(racine, "horizon"), { opacity: 1 }, depart);
  tracer(tl, un(racine, "horizon"), { duree, position: depart });
  lancerLaComete(tl, racine, "horizon", { duree, longueur: 0.12, position: depart });
  const phares = tous(racine, "phare");
  const jalons = tous(racine, "jalon");
  PLACES_DES_JALONS.forEach((x, i) => {
    const instant = depart + (duree * (x - HORIZON.debut)) / (HORIZON.fin - HORIZON.debut);
    tl.fromTo(phares[i], { opacity: 0, scale: 0.2 }, { opacity: 1, scale: 1, duration: 0.45, ease: "back.out(2.6)" }, instant);
    apparaitre(tl, jalons[i], { position: instant + 0.08, duree: 0.6 });
  });
  return tl;
}

/** La planche d'aplomb au pas `pas`, sans mouvement. */
export function poserLEtat(racine: HTMLElement, pas: number): void {
  const mosaique = pas === 4;
  const demain = pas >= 5;
  gsap.set(un(racine, "systeme"), { opacity: pas >= 4 ? 0 : 1 });
  gsap.set(tous(racine, "tuile"), { x: 0, y: 0, scale: 1, scaleX: 1, scaleY: 1, borderRadius: px(12), opacity: mosaique ? 1 : 0 });
  gsap.set(tous(racine, "tuile-contenu"), { opacity: mosaique ? 1 : 0 });
  tous(racine, "tuile").forEach((tuile) => tuile.setAttribute("data-allumee", "false"));
  gsap.set(un(racine, "annonce"), { opacity: mosaique ? 1 : 0, x: 0, y: 0 });
  gsap.set(un(racine, "chemise"), { opacity: demain ? 0 : 1, x: 0, filter: "none" });
  gsap.set(un(racine, "titre-affaire"), { opacity: demain ? 0 : 1, y: 0, filter: "none" });
  gsap.set(un(racine, "titre-demain"), { opacity: demain ? 1 : 0, y: 0, filter: "none" });
  gsap.set(un(racine, "legende"), { opacity: 1, y: 0, filter: "none" });
  gsap.set(un(racine, "horizon"), { opacity: demain ? 1 : 0, drawSVG: demain ? "100%" : "0%" });
  gsap.set(tous(racine, "phare"), { opacity: demain ? 1 : 0, scale: 1 });
  gsap.set(tous(racine, "jalon"), { opacity: demain ? 1 : 0, y: 0, filter: "none" });
}
