/**
 * La matière du deck de la Pitch Night — celle du héros de la landing avocats,
 * planche après planche : la nuit, le verre des planètes, l'anneau cyan, les
 * lueurs. Chaque valeur vient de la palette de nuit (`vitrine-de-nuit.tokens`) ou
 * du système du cabinet (`reseau.styles.ts`) : rien n'est inventé ici, tout est
 * recomposé à l'échelle d'une salle.
 *
 * L'ÉCHELLE. Chaque planche se compose sur une toile de px(2000) × px(1125)
 * (1 600 × 900 px rendus, 16:9), mise à l'échelle de l'écran d'un bloc
 * (`ToileDePlanche`) : sur un projecteur 1920 × 1080, px(N) rend environ N px.
 * Le texte le plus petit est px(18) — 17 px projetés.
 *
 * LES UNITÉS DE DESSIN. Une position se dit sur la grille 2 000 × 1 125 : px(N)
 * ou num(N) pour le HTML, N tel quel dans un SVG de `viewBox="0 0 2000 1125"`
 * posé sur toute la toile (`Calque`) — le viewBox applique le même facteur que
 * px(), et une comète tombe exactement sur la carte qu'elle vise.
 *
 * De nuit dans les deux thèmes, comme le héros : encres et fonds fixes.
 * Styles AVANT les composants (règle 18 — TDZ en chunk Vite).
 */
import { css, styled } from "styled-components";

import { color, withOpacity } from "@/shared/design-tokens/color";
import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";
import { num, px, shadow } from "@/shared/design-tokens/scale";
import { radius } from "@/shared/design-tokens/spacing";

/** La toile, en pixels rendus — ce que divise l'échelle de l'écran. */
export const TOILE = { largeur: num(2000), hauteur: num(1125) } as const;

/** Le verre d'une carte posée sur la nuit — celui de la carte d'un battement. */
export const verre = css`
  border: var(--border-thin) solid ${withOpacity(nuit.accent, 0.32)};
  border-radius: ${radius.md};
  background:
    linear-gradient(${nuit.verreClair}, ${nuit.verreBas}),
    ${withOpacity(nuit.fond, 0.9)};
  backdrop-filter: blur(${px(10)});
  box-shadow: ${shadow(`0 16px 40px ${withOpacity(nuit.ombrePortee, 0.5)}`)};
`;

/** Le verre allumé : l'anneau franc et sa lueur, quand un geste l'atteint. */
export const verreAllume = css`
  border-color: ${nuit.accent};
  box-shadow: ${shadow(
    `0 0 0 1px ${withOpacity(nuit.accent, 0.45)}, 0 0 36px ${withOpacity(nuit.accent, 0.35)}, 0 16px 40px ${withOpacity(nuit.ombrePortee, 0.5)}`,
  )};
`;

/**
 * Le disque d'une planète — le verre du système du cabinet : fond opaque, anneau
 * cyan, reflet en haut à gauche. Un cercle par son rayon : il porte un glyphe,
 * jamais un texte (règle 17). `--taille` le règle.
 */
export const disqueDeVerre = css`
  position: relative;
  display: grid;
  place-items: center;
  width: var(--taille);
  height: var(--taille);
  border-radius: calc(var(--taille) / 2);
  background: ${nuit.fond};
  color: ${nuit.accent};

  &::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    border: var(--border-thin) solid ${withOpacity(nuit.accent, 0.42)};
    background:
      radial-gradient(circle at 30% 25%, ${nuit.reflet}, transparent 60%),
      linear-gradient(${nuit.verre}, ${nuit.verre});
    box-shadow: ${shadow(`0 0 22px ${withOpacity(nuit.accent, 0.16)}`)};
  }

  svg {
    position: relative;
    width: 46%;
    height: 46%;
    overflow: visible;
  }
`;

/** L'éclat cyan d'un titre ou d'un chiffre — la lueur du terme central. */
export const lueur = css`
  text-shadow:
    0 0 ${px(30)} ${withOpacity(nuit.accent, 0.5)},
    0 0 ${px(64)} ${withOpacity(nuit.accent, 0.18)};
`;

/** Le surtitre d'une planche : capitales espacées, à l'encre d'accent. */
export const Surtitre = styled.p`
  margin: 0;
  font-size: ${px(22)};
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: ${nuit.accent};
`;

/** Le titre d'une planche — la grammaire du titre d'affiche du héros, à la taille d'une planche. */
export const TitreDePlanche = styled.h2`
  margin: 0;
  font-size: ${px(64)};
  font-weight: 900;
  line-height: 1.02;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: ${nuit.encre};
`;

/** Le mot qui porte le geste du logo — le C de Connect, du bleu au cyan (`AccentDeHeros`). */
export const Accent = styled.span`
  color: ${color.primaryCyan};
  background-image: linear-gradient(135deg, ${color.primary} 0%, ${color.primaryCyan} 100%);
  -webkit-background-clip: text;
  background-clip: text;
  padding-block: 0.15em;

  @supports (-webkit-background-clip: text) or (background-clip: text) {
    color: transparent;
  }
`;

/** La phrase sous un titre : l'encre douce, à la taille d'un chapeau. */
export const Chapeau = styled.p`
  margin: 0;
  font-size: ${px(30)};
  font-weight: 500;
  line-height: 1.4;
  color: ${nuit.encreDouce};
`;

/** Une petite légende posée sur la scène — jamais sous px(18). */
export const Legende = styled.p`
  margin: 0;
  font-size: ${px(19)};
  line-height: 1.4;
  color: ${nuit.encreDouce};
`;

/** Le filet de signature — le geste du C, qui se trace sous un titre. */
export const FiletDeSignature = styled.span`
  display: block;
  width: ${px(320)};
  height: ${px(4)};
  border-radius: ${radius.sm};
  background: ${nuit.signature};
  box-shadow: ${shadow(`0 0 18px ${withOpacity(nuit.accent, 0.45)}`)};
  transform-origin: left center;
`;

/** Le calque SVG d'une planche : toute la toile, en unités de dessin. */
export const Calque = styled.svg.attrs({ viewBox: "0 0 2000 1125", "aria-hidden": true, focusable: false })`
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
`;
