/**
 * Pitch Night 2026 — Incubateur du Barreau de Paris, jeudi 15 octobre, Maison du
 * Barreau. Raoul Delpech, président et cofondateur, au pupitre : trois minutes.
 *
 * Cinq planches, une matière — le système du cabinet de la landing avocats :
 *   1. le nom — les outils épars se relient, Juris-Power devient Juris-Connect ;
 *   2. un dossier traverse le cabinet ;
 *   3. la différence — quatre partis pris, la déontologie la première
 *      (restructuration demandée par William le 2026-10-14 à 22 h 40, croquis v5) ;
 *   4. le modèle, construit sous vos yeux ;
 *   5. merci — les planètes en orbite autour du QR.
 *
 * Croquis : `documentation/roadmap/presentations-catalogue/croquis/`. Publié par
 * `bash scripts/publier-deck.sh pitch-night-2026` ; aperçu local dans le showroom,
 * `/showroom/presentation-pitch-night-2026`.
 */
import { PresentationShell } from "@/shared/presentation-engine/PresentationShell";
import type { PresentationPart, PresentationScene } from "@/shared/presentation-engine/presentation-definition";

import { NOTES } from "./contenu";
import Accueil from "./planches/Accueil";
import Affaire from "./planches/affaire/Affaire";
import Difference from "./planches/difference/Difference";
import Merci from "./planches/Merci";
import Modele from "./planches/modele/Modele";

const SCENES: PresentationScene[] = [
  { id: "nom", label: "Le nom", dark: true, fragments: 1, targetMinutes: 0.33, render: () => <Accueil /> },
  { id: "affaire", label: "Un dossier traverse le cabinet", dark: true, fragments: 5, targetMinutes: 0.75, render: () => <Affaire /> },
  { id: "difference", label: "La différence", dark: true, fragments: 4, targetMinutes: 0.83, render: () => <Difference /> },
  { id: "modele", label: "Le modèle", dark: true, fragments: 5, targetMinutes: 0.75, render: () => <Modele /> },
  { id: "merci", label: "Merci", dark: true, targetMinutes: 0.25, render: () => <Merci /> },
];

/* Une partie par planche : la vue présentateur compare le temps réel au temps
   prévu, planche par planche — trois minutes en tout. */
const PARTS: PresentationPart[] = SCENES.reduce<{ parts: PresentationPart[]; cumul: number }>(
  (acc, scene, startIndex) => ({
    parts: [...acc.parts, { startIndex, label: scene.label, targetMinCumulative: acc.cumul }],
    cumul: acc.cumul + (scene.targetMinutes ?? 0),
  }),
  { parts: [], cumul: 0 },
).parts;

export default function PitchNight2026() {
  return (
    <PresentationShell
      title="Juris-Connect — Pitch Night 2026"
      scenes={SCENES}
      notes={NOTES}
      channelId="pitch-night-2026"
      parts={PARTS}
    />
  );
}
