/**
 * Un texte qui se recompose en un autre, lettre à lettre — le brouillage du
 * plugin ScrambleText (socle GSAP du moteur, `gsap.ts`).
 *
 * Né pour la Pitch Night 2026 : « Juris-Power » se recompose en
 * « Juris-Connect » au moment où le système du cabinet relie ses services — le
 * nom dit ce que le système fait. Réutilisable pour tout renommage montré.
 *
 * `vers` s'affiche quand `actif` est vrai, `de` sinon ; le passage se joue dans
 * les deux sens (un retour en arrière de l'orateur rejoue le brouillage à
 * l'envers). Au mouvement réduit, le texte change d'un coup.
 */
import { useEffect, useRef } from "react";
import { useReducedMotion } from "framer-motion";

import { gsap, inscrireGsap } from "@/shared/animations/gsap";

interface TexteQuiSeRecomposeProps {
  /** Le texte d'avant. */
  de: string;
  /** Le texte d'après. */
  vers: string;
  /** Vrai : le texte d'après. */
  actif: boolean;
  /** Durée du brouillage, en secondes (défaut 1,2). */
  duree?: number;
  /** Le jeu de caractères du brouillage (défaut : majuscules). */
  caracteres?: string;
}

export function TexteQuiSeRecompose({
  de,
  vers,
  actif,
  duree = 1.2,
  caracteres = "upperCase",
}: TexteQuiSeRecomposeProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const reduit = useReducedMotion() === true;
  const premier = useRef(true);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const cible = actif ? vers : de;
    // Au premier rendu, le texte est posé tel quel : rien ne se brouille à l'arrivée sur la planche.
    if (premier.current || reduit) {
      premier.current = false;
      el.textContent = cible;
      return;
    }
    inscrireGsap();
    const animation = gsap.to(el, {
      duration: duree,
      ease: "none",
      scrambleText: { text: cible, chars: caracteres, speed: 0.5, revealDelay: duree * 0.25 },
    });
    return () => {
      animation.kill();
    };
  }, [actif, de, vers, duree, caracteres, reduit]);

  return <span ref={ref}>{de}</span>;
}
