/**
 * Le cœur de la planche 3 — la sphère de connexions du héros, grande, et ses
 * quatre satellites en orbite : la déontologie, le délai, le secret, le
 * justiciable.
 *
 * L'horloge de la scène (une seule boucle) fait tourner la sphère et pose les
 * satellites sur leur orbite vue de biais : ce qui vient devant grossit et
 * passe devant. La TIMELINE de la planche, elle, tourne l'orbite d'un cran à
 * chaque clic (`etat.decalage`) pour amener le satellite de la partie devant ;
 * elle appelle `rendre` à chaque image de son tween, si bien que la planche se
 * pose juste même au mouvement réduit, horloge arrêtée.
 */
import { useLayoutEffect, useRef, type MutableRefObject } from "react";
import { useReducedMotion } from "framer-motion";

import { borner, ressort } from "@/shared/animations/scene/courbes";
import { opaciteSelonProfondeur, projeterSurOrbite } from "@/shared/animations/scene/geometrie";
import { useHorlogeDeScene } from "@/shared/animations/scene/horloge";
import { SphereDeConnexions, type PoigneeDeLaSphere } from "@/shared/animations/scene/SphereDeConnexions";
import { Glyphe } from "@/shared/components-common/systeme-du-cabinet/Glyphe";
import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";
import { num } from "@/shared/design-tokens/scale";

import { DIFFERENCE } from "../../contenu";
import { ANGLES_DES_SATELLITES, type EtatDuCoeur } from "./coeur.geometrie";
import {
  AnneauDuSatellite,
  COEUR,
  DisqueDuSatellite,
  HaloDuCoeur,
  NomDuSatellite,
  Satellite,
  Sphere,
} from "./difference.styles";

/** Les glyphes des satellites — en trait, dans un carré de 24, comme les planètes. */
const GLYPHES: Record<(typeof DIFFERENCE.parties)[number]["id"], string> = {
  deontologie: "M8 3h8v6l-2 2v3h-4v-3l-2-2z M4 17h16v4H4z",
  delai: "M4 6h16v15H4z M4 10h16 M8 3v5 M16 3v5 M9 15l2 2 4-4",
  secret: "M6 11h12v10H6z M8.5 11V8a3.5 3.5 0 0 1 7 0v3",
  justiciable: "M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18z M15.5 8.5l-2 5-5 2 2-5z",
};

export function Coeur({
  etat,
  rendreRef,
}: {
  etat: MutableRefObject<EtatDuCoeur>;
  /** La planche y reçoit `rendre`, pour poser les satellites depuis sa timeline. */
  rendreRef: MutableRefObject<() => void>;
}) {
  const reduit = useReducedMotion() === true;
  const scene = useRef<HTMLDivElement>(null);
  const sphere = useRef<PoigneeDeLaSphere>(null);
  const satellites = useRef<Array<HTMLDivElement | null>>([]);
  const horloge = useRef({ temps: 0, lacet: 0.6 });

  rendreRef.current = () => {
    const h = horloge.current;
    const arrivee = reduit ? 1 : borner((h.temps - 300) / 1300);
    const k = reduit ? 1 : ressort(arrivee);
    // Une respiration d'orbite, presque rien : la scène vit sans dériver de sa place.
    const souffle = reduit ? 0 : Math.sin(h.temps / 2600) * 0.05;
    const repere = {
      cx: num(COEUR.cx),
      cy: num(COEUR.cy),
      aplatissement: COEUR.aplatissement,
      focale: num(COEUR.focale),
    };
    DIFFERENCE.parties.forEach((_, i) => {
      const el = satellites.current[i];
      if (!el) return;
      const angle = ANGLES_DES_SATELLITES[i] + etat.current.decalage + souffle;
      const p = projeterSurOrbite(angle, num(COEUR.rayon) * k, repere);
      el.style.transform = `translate3d(${p.x.toFixed(1)}px, ${p.y.toFixed(1)}px, 0) translate(-50%, -${num(52)}px)`;
      el.style.opacity = (opaciteSelonProfondeur(p.profondeur, 0.5) * borner(arrivee * 2)).toFixed(3);
      el.style.zIndex = p.profondeur >= 0 ? "4" : "1";
      el.style.setProperty("--e", p.echelle.toFixed(3));
    });
    sphere.current?.dessiner(h.lacet, borner(h.temps / 1400), 0);
  };

  useHorlogeDeScene(
    (dt) => {
      horloge.current.temps += dt;
      horloge.current.lacet += (dt / 52_000) * Math.PI * 2;
      rendreRef.current();
    },
    { actif: !reduit, cible: scene },
  );

  // La première image, et la seule au mouvement réduit.
  useLayoutEffect(() => {
    if (reduit) horloge.current.temps = 10_000;
    rendreRef.current();
  }, [reduit, rendreRef]);

  return (
    <div ref={scene} style={{ position: "absolute", inset: 0 }} aria-hidden="true">
      <Sphere style={{ zIndex: 2 }}>
        <HaloDuCoeur />
        <SphereDeConnexions
          diametre={num(COEUR.diametre)}
          couleur={nuit.accent}
          nombreDePoints={110}
          voisins={3}
          densite={1.3}
          ref={sphere}
        />
      </Sphere>
      {DIFFERENCE.parties.map((partie, i) => (
        <Satellite
          key={partie.id}
          ref={(el) => {
            satellites.current[i] = el;
          }}
          data-role={`satellite-${partie.id}`}
        >
          <DisqueDuSatellite>
            <AnneauDuSatellite data-role={`anneau-${partie.id}`} />
            <Glyphe trace={GLYPHES[partie.id]} />
          </DisqueDuSatellite>
          <NomDuSatellite>{partie.nom}</NomDuSatellite>
        </Satellite>
      ))}
    </div>
  );
}
