/**
 * La géométrie du cœur de la planche 3 — où sont les satellites, et de combien
 * tourner l'orbite pour amener l'un d'eux devant. Hors du composant : un module
 * de composants n'exporte que des composants (rechargement à chaud).
 */
import { anglesDeLOrbite } from "@/shared/animations/scene/geometrie";

import { DIFFERENCE } from "../../contenu";

/** Les angles de départ : le premier satellite DEVANT (π/2), les autres à pas égal. */
export const ANGLES_DES_SATELLITES = anglesDeLOrbite(DIFFERENCE.parties.length, Math.PI / 2);

/** Le cran d'orbite qui amène le satellite `i` devant. */
export const decalagePour = (i: number): number => -i * ((2 * Math.PI) / DIFFERENCE.parties.length);

export interface EtatDuCoeur {
  /** La rotation d'orbite, tournée par la timeline de la planche. */
  decalage: number;
}
