/**
 * Chef d'orchestre du mouvement d'une scène (bibliothèque wahou 2026-07-05).
 *
 * Une scène « signature » construit UNE timeline GSAP paused avec des labels
 * `step-1`, `step-2`, … posés au début de chaque segment révélé par un
 * fragment. Le hook lit le fragment courant du moteur (FragmentStepContext) et
 * joue la timeline jusqu'au label correspondant — avancer = `tweenTo`, reculer
 * = `tweenTo` arrière, si `prefers-reduced-motion` = saut instantané à l'état
 * final du step (le contenu reste toujours atteignable, garde règle 43).
 *
 * Découplage volontaire : GSAP anime un sous-arbre DOM DISTINCT de celui géré
 * par framer-motion / View Transitions (jamais le même nœud) — cf. doctrine
 * WAHOU_CAPABILITIES. Cleanup via useGSAP (scope) : aucune fuite au démontage
 * de scène (remount-by-key du moteur).
 */
import { useGSAP } from "@gsap/react";
import { useContext, useEffect, useRef } from "react";
import type { RefObject } from "react";

import { FragmentStepContext } from "../fragments";
import { gsap, inscrireGsap } from "@/shared/animations/gsap";
import { mouvementReduit } from "@/shared/animations/mouvement-reduit";

/** Nom de label GSAP marquant l'état visuel après le `step`-ième fragment. */
export function stepLabel(step: number): string {
  return `step-${step}`;
}

export interface SceneTimelineHandle {
  timeline: gsap.core.Timeline | null;
}

/**
 * @param scope  conteneur de la scène (limite le cleanup GSAP)
 * @param build  construit la timeline paused ; poser `tl.addLabel(stepLabel(k))`
 *               à la FIN du segment que révèle le k-ième fragment — l'état
 *               atteint après ce clic (`step-0` : la fin de l'entrée sur la
 *               scène, avant tout clic)
 * @param options.naturelle  joue chaque segment à SA durée (une scène signature
 *               qui raconte en deux ou trois secondes) au lieu de la ramener à
 *               moins d'une seconde — ajouté pour la Pitch Night (2026-10-14).
 *               Une arrivée PAR L'ARRIÈRE (l'orateur revient sur la scène, ses
 *               fragments déjà révélés) saute à l'état final au lieu de rejouer
 *               toute la scène, et un pas en arrière se rembobine vite.
 */
export function useSceneTimeline(
  scope: RefObject<HTMLElement | null>,
  build: (tl: gsap.core.Timeline) => void,
  options: { naturelle?: boolean } = {},
): SceneTimelineHandle {
  const step = useContext(FragmentStepContext);
  const handle = useRef<SceneTimelineHandle>({ timeline: null });
  const buildRef = useRef(build);
  buildRef.current = build;
  const premierPas = useRef(true);

  useGSAP(
    () => {
      inscrireGsap();
      const tl = gsap.timeline({ paused: true });
      buildRef.current(tl);
      handle.current.timeline = tl;
      // État initial : rien de révélé (step 0). En showroom (step =
      // MAX_SAFE_INTEGER par défaut du context), on montre l'état final.
      if (step === Number.MAX_SAFE_INTEGER || mouvementReduit()) {
        tl.progress(1);
      }
    },
    { scope },
  );

  useEffect(() => {
    const tl = handle.current.timeline;
    if (!tl) return;
    // Showroom / hors-shell : tout révélé, pas de pilotage par fragment.
    if (step === Number.MAX_SAFE_INTEGER) return;
    const label = stepLabel(step);
    const target = tl.labels[label] != null ? label : step <= 0 ? 0 : tl.duration();
    const arrivee = premierPas.current;
    premierPas.current = false;
    if (mouvementReduit()) {
      tl.seek(target as number | string, false);
      return;
    }
    if (options.naturelle) {
      const position = typeof target === "string" ? tl.labels[target] : target;
      if (arrivee && step > 0) {
        tl.seek(position, false);
      } else if (position < tl.time()) {
        tl.tweenTo(position, { duration: Math.min(0.6, tl.time() - position) });
      } else {
        tl.tweenTo(position);
      }
      return;
    }
    tl.tweenTo(target, { duration: Math.min(0.9, 0.35 + step * 0.12) });
  }, [step, options.naturelle]);

  return handle.current;
}
