/**
 * Le dossier Martin — la chemise où chaque service pose son tampon quand le
 * trait du battement l'atteint. Un tampon tombe (il arrive grand, penché, flou,
 * et se pose), son disque s'allume d'une onde, et le dossier tout entier
 * s'éclaire une fois. L'affaire s'y lit dans l'ordre où elle s'est faite :
 * saisie une fois, elle traverse le cabinet.
 */
import { Fragment as Groupe } from "react";

import { Glyphe } from "@/shared/components-common/systeme-du-cabinet/Glyphe";
import { BATTEMENTS } from "@/shared/components-common/systeme-du-cabinet/systeme.flux";
import { NOEUDS_DU_RESEAU } from "@/shared/components-common/systeme-du-cabinet/systeme.reseau";

import { DOSSIER, TEMPS_DE_L_AFFAIRE } from "../../contenu";
import {
  Chemise,
  Corps,
  DisqueDuTampon,
  EclatDuCorps,
  Onglet,
  SousTitre,
  Tampon,
  TamponDetail,
  TamponTexte,
  TamponTitre,
  Temps,
} from "./affaire.styles";

/** Le glyphe d'un tampon : celui du service où le trait arrive. */
const glypheDuTampon = (battement: number): string => {
  const vers = BATTEMENTS[battement]?.vers;
  return NOEUDS_DU_RESEAU.find((n) => n.id === vers)?.glyphe ?? "";
};

const GLYPHE_DU_DOSSIER = "M3 6h6l2 3h10v11H3z";

export function Dossier({ poses, eclat }: { poses: number; eclat: number }) {
  let rang = 0;
  return (
    <Chemise data-role="chemise" aria-label={`${DOSSIER.nom} — ${poses} étapes franchies`}>
      <Onglet>
        <Glyphe trace={GLYPHE_DU_DOSSIER} />
        {DOSSIER.nom}
      </Onglet>
      <Corps data-role="corps">
        {eclat > 0 && <EclatDuCorps key={eclat} aria-hidden="true" />}
        <SousTitre>{DOSSIER.sousTitre}</SousTitre>
        {TEMPS_DE_L_AFFAIRE.map((temps) => {
          const premier = rang;
          rang += temps.tampons.length;
          if (poses <= premier) return null;
          return (
            <Groupe key={temps.titre}>
              <Temps>{temps.titre}</Temps>
              {temps.tampons.map((tampon, j) =>
                premier + j < poses ? (
                  <Tampon key={tampon.titre} data-role="tampon">
                    <DisqueDuTampon>
                      <Glyphe trace={glypheDuTampon(tampon.battement)} />
                    </DisqueDuTampon>
                    <TamponTexte>
                      <TamponTitre>{tampon.titre}</TamponTitre>
                      <TamponDetail>{tampon.detail}</TamponDetail>
                    </TamponTexte>
                  </Tampon>
                ) : null,
              )}
            </Groupe>
          );
        })}
      </Corps>
    </Chemise>
  );
}
