/**
 * Planche 5 — merci (≈ 15 s). Croquis v4 validé.
 *
 * La boucle se referme sur l'image du début : les planètes du système du
 * cabinet reviennent en orbite — autour du QR, cette fois, qui se dessine
 * ligne à ligne sous un trait de lumière. Le QR mène à l'inscription avocat.
 * L'orbite passe DERRIÈRE la carte du QR par le haut et DEVANT elle sous son
 * bord : aucune planète ne couvre jamais un module, le code reste lisible à
 * tout instant.
 */
import { useLayoutEffect, useRef } from "react";
import { useReducedMotion } from "framer-motion";
import { QRCodeSVG } from "qrcode.react";
import { styled } from "styled-components";

import { borner, ressort } from "@/shared/animations/scene/courbes";
import { anglesDeLOrbite, opaciteSelonProfondeur, projeterSurOrbite } from "@/shared/animations/scene/geometrie";
import { useHorlogeDeScene } from "@/shared/animations/scene/horloge";
import { Glyphe } from "@/shared/components-common/systeme-du-cabinet/Glyphe";
import { NOEUDS_DU_RESEAU } from "@/shared/components-common/systeme-du-cabinet/systeme.reseau";
import { color, withOpacity } from "@/shared/design-tokens/color";
import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";
import { num, px, shadow } from "@/shared/design-tokens/scale";
import { radius } from "@/shared/design-tokens/spacing";
import { stepLabel, useSceneTimeline } from "@/shared/presentation-engine/motion/use-scene-timeline";

import { MERCI } from "../contenu";
import { Accent, disqueDeVerre, lueur } from "../pitch.styles";
import { apparaitre, COURBES, reveler } from "../scene/gestes";
import { ToileDePlanche } from "../scene/ToileDePlanche";

/* L'orbite, en unités de dessin : sous le centre du QR, pour que sa moitié
   avant passe sous la carte et sa moitié arrière derrière elle. */
const ORBITE = { cx: 1430, cy: 610, rayon: 455, aplatissement: 0.3, focale: 1500, tourMs: 64_000 };
const SERVICES = NOEUDS_DU_RESEAU.filter((n) => !n.tiroir);
const ANGLES = anglesDeLOrbite(SERVICES.length, 0.35);

const Colonne = styled.div`
  position: absolute;
  left: ${px(120)};
  top: 0;
  bottom: 0;
  width: ${px(800)};
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: ${px(26)};
`;

const GrandMerci = styled.h2`
  margin: 0;
  font-size: ${px(150)};
  font-weight: 900;
  line-height: 0.95;
  letter-spacing: -0.03em;
  color: ${nuit.encre};
  ${lueur}
`;

const Avantage = styled.p`
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: ${px(6)};
  font-size: ${px(30)};
  line-height: 1.3;
  color: ${nuit.encreCourante};
`;

const AvantageFort = styled.span`
  font-size: ${px(56)};
  font-weight: 900;
  line-height: 1.05;
  text-transform: uppercase;
  letter-spacing: -0.01em;
`;

const Domaine = styled.p`
  margin: ${px(10)} 0 0;
  font-size: ${px(40)};
  font-weight: 800;
  letter-spacing: 0.02em;
  color: ${nuit.encre};
`;

const Equipe = styled.ul`
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: ${px(6)};
  font-size: ${px(22)};
  color: ${nuit.encreDouce};

  strong {
    color: ${nuit.encre};
    font-weight: 700;
  }
`;

const Orbite = styled.div`
  position: absolute;
  inset: 0;
`;

const Carte = styled.div`
  position: absolute;
  left: ${px(ORBITE.cx - 190)};
  top: ${px(300)};
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: ${px(16)};
  width: ${px(380)};
`;

const Plaque = styled.div`
  position: relative;
  padding: ${px(22)};
  border-radius: ${radius.lg};
  background: ${color.white};
  box-shadow: ${shadow(
    `0 0 0 2px ${withOpacity(nuit.accent, 0.6)}, 0 0 60px ${withOpacity(nuit.accent, 0.45)}, 0 24px 60px ${withOpacity(nuit.ombrePortee, 0.6)}`,
  )};
  overflow: hidden;

  svg {
    display: block;
  }
`;

/** Le trait de lumière qui dessine le QR, de haut en bas. */
const Balayage = styled.span`
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: ${px(6)};
  background: linear-gradient(90deg, transparent, ${nuit.accent}, ${nuit.eclat}, ${nuit.accent}, transparent);
  box-shadow: ${shadow(`0 0 24px ${nuit.accent}`)};
  opacity: 0;
`;

const Invite = styled.p`
  margin: 0;
  font-size: ${px(22)};
  font-weight: 600;
  color: ${nuit.encreCourante};
`;

const Planete = styled.span`
  --taille: ${px(58)};
  ${disqueDeVerre}
  position: absolute;
  left: 0;
  top: 0;
  will-change: transform, opacity;
`;

function OrbiteDuMerci() {
  const reduit = useReducedMotion() === true;
  const cadre = useRef<HTMLDivElement>(null);
  const disques = useRef<Array<HTMLSpanElement | null>>([]);
  const temps = useRef(0);
  const poserRef = useRef<(t: number) => void>(() => undefined);

  poserRef.current = (t: number) => {
    const arrivee = reduit ? 1 : borner((t - 500) / 1500);
    const k = reduit ? 1 : ressort(arrivee);
    const scene = {
      cx: num(ORBITE.cx),
      cy: num(ORBITE.cy),
      aplatissement: ORBITE.aplatissement,
      focale: num(ORBITE.focale),
    };
    SERVICES.forEach((_, i) => {
      const el = disques.current[i];
      if (!el) return;
      const angle = ANGLES[i] + (reduit ? 0 : (t / ORBITE.tourMs) * Math.PI * 2);
      const p = projeterSurOrbite(angle, num(ORBITE.rayon) * k, scene);
      el.style.transform = `translate3d(${p.x.toFixed(1)}px, ${p.y.toFixed(1)}px, 0) translate(-50%, -50%) scale(${p.echelle.toFixed(3)})`;
      el.style.opacity = (opaciteSelonProfondeur(p.profondeur, 0.4) * borner(arrivee * 2)).toFixed(3);
      el.style.zIndex = p.profondeur >= 0 ? "3" : "1";
    });
  };

  useHorlogeDeScene(
    (dt) => {
      temps.current += dt;
      poserRef.current(temps.current);
    },
    { actif: !reduit, cible: cadre },
  );

  // Une image posée à l'arrivée (et la seule au mouvement réduit) ; l'horloge fait le reste.
  useLayoutEffect(() => {
    poserRef.current(temps.current);
  }, [reduit]);

  return (
    <Orbite ref={cadre} aria-hidden="true">
      {SERVICES.map((service, i) => (
        <Planete
          key={service.id}
          ref={(el) => {
            disques.current[i] = el;
          }}
        >
          <Glyphe trace={service.glyphe} />
        </Planete>
      ))}
    </Orbite>
  );
}

export default function Merci() {
  const scene = useRef<HTMLDivElement>(null);

  useSceneTimeline(
    scene,
    (tl) => {
      const r = scene.current;
      if (!r) return;
      const q = (role: string) => r.querySelector(`[data-role="${role}"]`);
      reveler(tl, q("merci"), { par: "chars", ecart: 0.06 });
      tl.fromTo(q("plaque"), { opacity: 0, scale: 0.9 }, { opacity: 1, scale: 1, duration: 0.6, ease: COURBES.sortie }, "-=0.3");
      tl.fromTo(q("qr"), { clipPath: "inset(0 0 100% 0)" }, { clipPath: "inset(0 0 0% 0)", duration: 1.4, ease: "none" }, "-=0.1");
      tl.fromTo(
        q("balayage"),
        { top: "0%", opacity: 1 },
        { top: "100%", opacity: 1, duration: 1.4, ease: "none" },
        "<",
      );
      tl.to(q("balayage"), { opacity: 0, duration: 0.3 });
      apparaitre(tl, q("invite"), { position: "-=0.4" });
      apparaitre(tl, q("avantage"), { position: "-=1.6", duree: 0.8 });
      apparaitre(tl, q("domaine"), { position: "-=0.3" });
      apparaitre(tl, q("equipe"), { position: "-=0.3" });
      tl.addLabel(stepLabel(0));
    },
    { naturelle: true },
  );

  return (
    <ToileDePlanche etiquette={`Merci. ${MERCI.avantage.join(" ")} ${MERCI.domaine}.`}>
      <div ref={scene} style={{ position: "absolute", inset: 0 }}>
        <Colonne>
          <GrandMerci data-role="merci">{MERCI.titre}</GrandMerci>
          <Avantage data-role="avantage">
            <AvantageFort>
              <Accent>{MERCI.avantage[0]}</Accent>
            </AvantageFort>
            <span>
              {MERCI.avantage[1]} {MERCI.avantage[2]}
            </span>
          </Avantage>
          <Domaine data-role="domaine">{MERCI.domaine}</Domaine>
          <Equipe data-role="equipe">
            {MERCI.equipe.map((p) => (
              <li key={p.nom}>
                <strong>{p.nom}</strong> — {p.role}
              </li>
            ))}
          </Equipe>
        </Colonne>

        <OrbiteDuMerci />
        <Carte>
          <Plaque data-role="plaque">
            <div data-role="qr">
              <QRCodeSVG
                value={MERCI.inscription}
                size={num(300)}
                level="M"
                marginSize={0}
                fgColor={nuit.fond}
                bgColor={color.white}
                title={`Inscription — ${MERCI.domaine}`}
              />
            </div>
            <Balayage data-role="balayage" />
          </Plaque>
          <Invite data-role="invite">{MERCI.scanner}</Invite>
        </Carte>
      </div>
    </ToileDePlanche>
  );
}
