/**
 * Demain — l'horizon qui traverse la planche au cinquième clic. La mosaïque est
 * aspirée dans le premier jalon (l'agrégateur : le cabinet réuni), puis l'horizon
 * se trace de gauche à droite, une comète à sa tête, et chaque jalon s'allume
 * quand le trait l'atteint. Seulement l'à-venir, chacun adossé à son chantier
 * (`DEMAIN`, `contenu.ts`).
 */
import { useId } from "react";

import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";

import { DEMAIN } from "../../contenu";
import { Comete } from "../../scene/Comete";
import { CHEMIN_DE_L_HORIZON, PLACES_DES_JALONS } from "./affaire.geometrie";
import { HORIZON, Jalon, JalonTexte, JalonTitre, Phare } from "./affaire.styles";

/** Les tracés de l'horizon : à poser dans le calque SVG de la planche. */
export function TraitsDeLHorizon() {
  const degrade = `horizon-${useId().replace(/:/g, "")}`;
  return (
    <>
      <path
        data-role="horizon"
        d={CHEMIN_DE_L_HORIZON}
        fill="none"
        stroke={`url(#${degrade})`}
        strokeWidth={3}
        strokeLinecap="round"
        style={{ opacity: 0 }}
      />
      <defs>
        <linearGradient id={degrade} x1={HORIZON.debut} x2={HORIZON.fin} y1={0} y2={0} gradientUnits="userSpaceOnUse">
          <stop offset="0" stopColor={nuit.marque} stopOpacity="0.25" />
          <stop offset="0.5" stopColor={nuit.accent} stopOpacity="0.9" />
          <stop offset="1" stopColor={nuit.accent} stopOpacity="0.3" />
        </linearGradient>
      </defs>
      <Comete nom="horizon" d={CHEMIN_DE_L_HORIZON} piste={false} epaisseur={4} />
    </>
  );
}

export function Demain() {
  return (
    <>
      {DEMAIN.map((item, i) => (
        <Phare key={`phare-${item.titre}`} data-role="phare" $x={PLACES_DES_JALONS[i]} />
      ))}
      {DEMAIN.map((item, i) => (
        <Jalon key={item.titre} data-role="jalon" $x={PLACES_DES_JALONS[i]}>
          <JalonTitre>{item.titre}</JalonTitre>
          <JalonTexte>{item.texte}</JalonTexte>
        </Jalon>
      ))}
    </>
  );
}
