/**
 * Styles de la planche 3 — la différence.
 *
 * La composition, en unités de dessin (2 000 × 1 125, `pitch.styles`) :
 *   · le titre et son chapeau, en haut à gauche ;
 *   · le cœur, à gauche : la sphère de connexions du héros (centre 500, 660) et
 *     ses quatre satellites en orbite ;
 *   · le panneau de la partie, à droite (x 1 010 → 1 880) : son rang, son titre,
 *     sa preuve animée, ses lignes. Les quatre panneaux occupent la même place ;
 *     la timeline les fait entrer et sortir.
 * Styles AVANT les composants (règle 18).
 */
import { css, styled } from "styled-components";

import { withOpacity } from "@/shared/design-tokens/color";
import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";
import { px, shadow } from "@/shared/design-tokens/scale";
import { radius } from "@/shared/design-tokens/spacing";

import { disqueDeVerre, verre } from "../../pitch.styles";

/** Le cœur : la sphère et l'orbite de ses satellites, en unités de dessin. */
export const COEUR = { cx: 500, cy: 660, diametre: 450, rayon: 380, aplatissement: 0.3, focale: 1500 } as const;

const absolu = (x: number, y: number) => css`
  position: absolute;
  left: ${px(x)};
  top: ${px(y)};
`;

export const Entete = styled.div`
  ${absolu(120, 60)}
  display: flex;
  flex-direction: column;
  gap: ${px(12)};
  max-width: ${px(860)};
`;

export const Sphere = styled.div`
  ${absolu(COEUR.cx - COEUR.diametre / 2, COEUR.cy - COEUR.diametre / 2)}
  width: ${px(COEUR.diametre)};
  height: ${px(COEUR.diametre)};
`;

export const HaloDuCoeur = styled.div`
  position: absolute;
  inset: -30%;
  border-radius: 50%;
  background: radial-gradient(
    closest-side,
    ${withOpacity(nuit.accent, 0.18)},
    ${withOpacity(nuit.marque, 0.08)} 55%,
    transparent
  );
`;

/** Un satellite : posé par l'horloge (transform, z-index), son disque grandit avec la profondeur. */
export const Satellite = styled.div`
  position: absolute;
  left: 0;
  top: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: ${px(12)};
  width: ${px(260)};
  transform: translate3d(-9999px, -9999px, 0);
  will-change: transform, opacity;
`;

export const DisqueDuSatellite = styled.span`
  --taille: ${px(104)};
  ${disqueDeVerre}
  transform: scale(var(--e, 1));
`;

/** L'anneau qui s'allume quand la partie a été dite — et le reste. */
export const AnneauDuSatellite = styled.span`
  position: absolute;
  inset: calc(-1 * var(--border-medium));
  border-radius: inherit;
  border: var(--border-medium) solid ${nuit.accent};
  box-shadow: ${shadow(`0 0 0 1px ${withOpacity(nuit.accent, 0.5)}, 0 0 40px ${withOpacity(nuit.accent, 0.6)}`)};
  opacity: 0;
`;

export const NomDuSatellite = styled.span`
  font-size: ${px(24)};
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: ${nuit.encre};
  text-shadow: 0 0 ${px(12)} ${nuit.fond};
`;

/* ── Le panneau d'une partie ──────────────────────────────────────────── */

/** Invisible jusqu'à son clic : la timeline le pose visible quand il entre. */
export const Panneau = styled.section`
  ${absolu(1010, 240)}
  width: ${px(870)};
  display: flex;
  flex-direction: column;
  gap: ${px(22)};
  opacity: 0;
`;

export const Rang = styled.span`
  font-size: ${px(20)};
  font-weight: 800;
  letter-spacing: 0.22em;
  color: ${nuit.accent};
`;

export const TitreDePartie = styled.h3`
  margin: 0;
  font-size: ${px(48)};
  font-weight: 900;
  line-height: 1.08;
  letter-spacing: -0.01em;
  text-transform: uppercase;
  color: ${nuit.encre};
`;

export const Lignes = styled.ul`
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: ${px(14)};
`;

export const Ligne = styled.li`
  position: relative;
  padding-left: ${px(26)};
  font-size: ${px(23)};
  line-height: 1.38;
  color: ${nuit.encreCourante};

  &::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0.62em;
    width: ${px(10)};
    height: ${px(10)};
    border-radius: ${radius.xs};
    background: ${nuit.accent};
    box-shadow: ${shadow(`0 0 10px ${withOpacity(nuit.accent, 0.8)}`)};
  }
`;

