/**
 * Planche 2 — un dossier traverse le cabinet (≈ 45 s, cinq clics). Croquis v4
 * validé ; ses écarts, relus contre le code le 2026-10-14 (étude des parcours),
 * sont dits dans `contenu.ts` : deux cartes de la landing en disaient plus que le
 * produit, et deux promesses de « Demain » étaient déjà là ou rejetées.
 *
 * Le système du cabinet de la landing, piloté : à chaque clic, un temps de
 * l'affaire. Ses battements partent un par un ; quand le trait arrive à un
 * service, une comète file de la planète au dossier Martin et y pose son tampon.
 * Au quatrième clic, chaque planète devient sa tuile (la mosaïque) ; au
 * cinquième, la mosaïque est aspirée dans le premier jalon de « Demain ».
 */
import { useContext, useEffect, useLayoutEffect, useRef, useState } from "react";
import { useReducedMotion } from "framer-motion";

import { gsap } from "@/shared/animations/gsap";
import { BATTEMENTS } from "@/shared/components-common/systeme-du-cabinet/systeme.flux";
import { SystemeDuCabinet } from "@/shared/components-common/systeme-du-cabinet/SystemeDuCabinet";
import { FragmentStepContext } from "@/shared/presentation-engine/fragments";

import { TEMPS_DE_L_AFFAIRE } from "../../contenu";
import { Accent, Calque, TitreDePlanche } from "../../pitch.styles";
import { CielDeConnexions } from "../../scene/CielDeConnexions";
import { Comete } from "../../scene/Comete";
import { ToileDePlanche } from "../../scene/ToileDePlanche";
import { CadreDuSysteme, Entete, Legende } from "./affaire.styles";
import {
  CADENCE,
  changerLaLegende,
  entrer,
  LEGENDES,
  PERIODE_MS,
  poserLEtat,
  posesALaFinDu,
  TRAIT_MS,
  versDemain,
  versLaMosaique,
  volerVersLeDossier,
} from "./choregraphie";
import { Demain, TraitsDeLHorizon } from "./Demain";
import { Dossier } from "./Dossier";
import { Mosaique } from "./Mosaique";

/** Le pas de la planche : hors du moteur (showroom), tout est révélé. */
const DERNIER_PAS = 5;

export default function Affaire() {
  const etape = useContext(FragmentStepContext);
  const pas = Math.min(etape, DERNIER_PAS);
  const reduit = useReducedMotion() === true;
  const racine = useRef<HTMLDivElement>(null);
  const [battement, setBattement] = useState(-1);
  const [poses, setPoses] = useState(() => posesALaFinDu(pas));
  const [eclat, setEclat] = useState(0);
  const precedent = useRef<number | null>(null);
  /* L'arrivée seulement : le pas et le mouvement réduit du premier rendu. Les
     pas suivants passent par l'effet d'après. */
  const arrivee = useRef({ pas, reduit });

  // L'arrivée : la planche d'aplomb à son pas, puis l'entrée si l'on arrive au début.
  useLayoutEffect(() => {
    const r = racine.current;
    const { pas: pasDArrivee, reduit: sansMouvement } = arrivee.current;
    if (!r) return;
    poserLEtat(r, pasDArrivee);
    changerLaLegende(r, pasDArrivee, true);
    if (pasDArrivee > 0 || sansMouvement) return;
    const tl = entrer(r);
    return () => {
      tl.progress(1).kill();
    };
  }, []);

  useEffect(() => {
    const r = racine.current;
    const avant = precedent.current;
    precedent.current = pas;
    if (!r || avant === null || avant === pas) return;

    const minuteurs: number[] = [];
    let transition: gsap.core.Timeline | null = null;
    const unPasEnAvant = pas === avant + 1;

    if (!unPasEnAvant || reduit) {
      // Un saut, un pas en arrière, ou le mouvement réduit : l'état, sans le geste.
      setBattement(-1);
      setPoses(posesALaFinDu(pas));
      poserLEtat(r, pas);
      changerLaLegende(r, pas, true);
      return;
    }

    changerLaLegende(r, pas, false);
    if (pas <= TEMPS_DE_L_AFFAIRE.length) {
      // Un temps de l'affaire : ses battements un par un, chacun pose son tampon.
      const base = posesALaFinDu(pas - 1);
      setPoses((p) => Math.max(p, base));
      TEMPS_DE_L_AFFAIRE[pas - 1].tampons.forEach((tampon, j) => {
        const depart = j * PERIODE_MS;
        minuteurs.push(window.setTimeout(() => setBattement(tampon.battement), depart));
        minuteurs.push(
          window.setTimeout(() => volerVersLeDossier(r, BATTEMENTS[tampon.battement].vers), depart + TRAIT_MS),
        );
        minuteurs.push(
          window.setTimeout(() => {
            setPoses((p) => Math.max(p, base + j + 1));
            setEclat((e) => e + 1);
          }, depart + TRAIT_MS + 520),
        );
      });
    } else if (pas === TEMPS_DE_L_AFFAIRE.length + 1) {
      transition = versLaMosaique(r);
    } else {
      transition = versDemain(r);
    }

    return () => {
      minuteurs.forEach((m) => window.clearTimeout(m));
      // Un clic qui arrive avant la fin du geste le termine d'abord.
      transition?.progress(1).kill();
      if (pas <= TEMPS_DE_L_AFFAIRE.length) setPoses((p) => Math.max(p, posesALaFinDu(pas)));
    };
  }, [pas, reduit]);

  return (
    <ToileDePlanche etiquette={`Un dossier traverse le cabinet. ${LEGENDES[Math.max(0, pas)]}.`}>
      <CielDeConnexions x={1900} y={-80} diametre={1100} intensite={0.16} />
      <div ref={racine} style={{ position: "absolute", inset: 0 }}>
        <Entete>
          <TitreDePlanche data-role="titre-affaire">
            Un dossier traverse <Accent>le cabinet</Accent>
          </TitreDePlanche>
          <TitreDePlanche data-role="titre-demain" aria-hidden={pas < DERNIER_PAS}>
            Et <Accent>demain</Accent>
          </TitreDePlanche>
        </Entete>
        <Legende data-role="legende">{LEGENDES[0]}</Legende>

        <CadreDuSysteme data-role="systeme">
          <SystemeDuCabinet cadre="planche" battement={battement} cadence={CADENCE} sansCarte />
        </CadreDuSysteme>

        <Mosaique />
        <Dossier poses={poses} eclat={eclat} />
        <Demain />

        <Calque>
          <Comete nom="vol" d="M0 0L1 1" piste={false} epaisseur={3} />
          <TraitsDeLHorizon />
        </Calque>
      </div>
    </ToileDePlanche>
  );
}
