/**
 * Les quatre panneaux de la planche 3 — un par partie, tous à la même place.
 * Chacun porte son rang, son titre, sa PREUVE (ce qui se voit jouer) et ses
 * lignes. Rien ne bouge ici : la timeline de la planche fait entrer, jouer et
 * sortir chaque panneau, en lisant ses `data-role`.
 */
import { Glyphe } from "@/shared/components-common/systeme-du-cabinet/Glyphe";

import { DIFFERENCE } from "../../contenu";
import { Comete } from "../../scene/Comete";
import {
  AnneauDuSatellite,
  Calendrier,
  CarteDeDate,
  Chemin,
  DateDuCalendrier,
  DateLegende,
  Etape,
  Fleche,
  Jeton,
  Ligne,
  Lignes,
  Masque,
  MasqueLegende,
  MasquePhrase,
  NomDEtape,
  Panneau,
  PointDEtape,
  Rang,
  Rature,
  Sceau,
  Tampon,
  TamponArticle,
  TamponRegle,
  Tampons,
  TamponTete,
  TamponTexte,
  TitreDePartie,
} from "./difference.styles";

const [DEONTOLOGIE, DELAI, SECRET, JUSTICIABLE] = DIFFERENCE.parties;
const TOTAL = DIFFERENCE.parties.length;

/** Les glyphes des trois étapes du justiciable. */
const GLYPHES_DES_ETAPES = [
  "M5 4h14v12H9l-4 4z M8 8h8 M8 11h5",
  "M4 7h16v13H4z M9 7V4h6v3 M4 12h16",
  "M12 4a8 8 0 1 0 0 16 8 8 0 0 0 0-16z M12 8v4l3 2",
];

/** Le chemin du justiciable, dans le repère de son bloc (870 × 200). */
const CHEMIN = "M110 52Q272 -10 435 52T760 52";
const PLACES_DES_ETAPES = [110, 435, 760];

function EnTete({ rang, titre }: { rang: number; titre: string }) {
  return (
    <>
      <Rang data-role="rang">{`${rang} / ${TOTAL}`}</Rang>
      <TitreDePartie data-role="titre">{titre}</TitreDePartie>
    </>
  );
}

function LesLignes({ lignes }: { lignes: readonly string[] }) {
  return (
    <Lignes>
      {lignes.map((ligne) => (
        <Ligne key={ligne} data-role="ligne">
          {ligne}
        </Ligne>
      ))}
    </Lignes>
  );
}

export function Panneaux() {
  return (
    <>
      <Panneau data-role={`partie-${DEONTOLOGIE.id}`} aria-label={DEONTOLOGIE.titre}>
        <EnTete rang={1} titre={DEONTOLOGIE.titre} />
        <Tampons>
          {DEONTOLOGIE.tampons.map((t) => (
            <Tampon key={t.regle} data-role="tampon">
              <TamponTete>
                <TamponRegle>{t.regle}</TamponRegle>
                <TamponArticle>{t.article}</TamponArticle>
              </TamponTete>
              <TamponTexte>{t.texte}</TamponTexte>
            </Tampon>
          ))}
        </Tampons>
      </Panneau>

      <Panneau data-role={`partie-${DELAI.id}`} aria-label={DELAI.titre}>
        <EnTete rang={2} titre={DELAI.titre} />
        <Calendrier>
          <CarteDeDate $x={0} data-role="date-acte">
            <DateDuCalendrier>{DELAI.calendrier.acte}</DateDuCalendrier>
            <DateLegende>{DELAI.calendrier.evenement}</DateLegende>
          </CarteDeDate>
          <Fleche $x={232} $largeur={176} data-role="fleche">
            {DELAI.calendrier.delai}
          </Fleche>
          <CarteDeDate $x={420} data-role="date-tombe">
            <DateDuCalendrier>{DELAI.calendrier.tombe}</DateDuCalendrier>
            <DateLegende>un dimanche</DateLegende>
            <Rature data-role="rature" />
          </CarteDeDate>
          <CarteDeDate $x={650} $allumee data-role="date-reportee">
            <DateDuCalendrier>{DELAI.calendrier.reporte}</DateDuCalendrier>
            <DateLegende>premier jour ouvrable suivant</DateLegende>
          </CarteDeDate>
          <Sceau $x={650} data-role="sceau">
            {DELAI.calendrier.article}
          </Sceau>
        </Calendrier>
        <LesLignes lignes={DELAI.lignes} />
      </Panneau>

      <Panneau data-role={`partie-${SECRET.id}`} aria-label={SECRET.titre}>
        <EnTete rang={3} titre={SECRET.titre} />
        <Masque>
          <MasqueLegende data-role="masque-ligne">Vous écrivez</MasqueLegende>
          <MasquePhrase data-role="masque-ligne">{SECRET.masque.phrase}</MasquePhrase>
          <MasqueLegende data-role="masque-ligne">Le modèle reçoit</MasqueLegende>
          <MasquePhrase data-role="masque-ligne">
            <Jeton data-role="jeton">{SECRET.masque.nom}</Jeton>
            {SECRET.masque.phrase.slice(SECRET.masque.nom.length)}
          </MasquePhrase>
        </Masque>
        <LesLignes lignes={SECRET.lignes} />
      </Panneau>

      <Panneau data-role={`partie-${JUSTICIABLE.id}`} aria-label={JUSTICIABLE.titre}>
        <EnTete rang={4} titre={JUSTICIABLE.titre} />
        <Chemin>
          <svg
            viewBox="0 0 870 200"
            aria-hidden="true"
            focusable="false"
            style={{ position: "absolute", inset: 0, width: "100%", height: "100%", overflow: "visible" }}
          >
            <Comete nom="parcours" d={CHEMIN} epaisseur={3} />
          </svg>
          {JUSTICIABLE.chemin.map((nom, i) => (
            <Etape key={nom} $x={PLACES_DES_ETAPES[i]} data-role="etape">
              <PointDEtape>
                <AnneauDuSatellite data-role="anneau-etape" />
                <Glyphe trace={GLYPHES_DES_ETAPES[i]} />
              </PointDEtape>
              <NomDEtape>{nom}</NomDEtape>
            </Etape>
          ))}
        </Chemin>
        <LesLignes lignes={JUSTICIABLE.lignes} />
      </Panneau>
    </>
  );
}
